  pages = {
    ["alonsus-faol"] = {
      title = "Alonsus Faol",
      text = {
        { "Alonsus Faol dirigeait les clercs de Comté-du-Nord avant la Première Guerre, et quand Hurlevent tomba, et l'abbaye avec elle, le vieil homme partit vers le nord avec les réfugiés. En Lordaeron, devenu archevêque, il donna une épée à l'Église de la Lumière sacrée : il fonda les chevaliers de la Main d'argent et oignit son apprenti, Uther, premier des paladins." },
        { "Son œuvre ne s'arrêta pas au champ de bataille. Une plaque de la cathédrale de Hurlevent dit qu'il la commença à Stratholme, aida à refonder la Confrérie de Comté-du-Nord après la Deuxième Guerre et réunit les fonds pour rebâtir Hurlevent elle-même. Il mourut avant l'arrivée de la peste, de rien de pire que la vieillesse, pour autant qu'on le sache." },
        { "C'est ici, dit-on, qu'il repose. Avant le Fléau, c'était un lieu de pèlerinage. Aujourd'hui, il rassemble les morts du Monastère écarlate, et personne ne vient le pleurer. Il méritait mieux, et l'ordre qu'il a fondé aussi." },
      },
    },
    ["ancients"] = {
      title = "Les Anciens",
      text = {
        { "Les Anciens sont les plus vieux arbres des forêts des elfes de la nuit, devenus assez sages pour penser et assez forts pour marcher. Pendant la guerre des Anciens, Cénarius les fit se lever des bois enchantés et les mena contre la Légion ardente, une armée d'hommes-arbres marchant sur la cité même de la reine ; pendant la Troisième Guerre, ils marchèrent de nouveau." },
        { "Ils montent toujours la garde. Des anciens protecteurs veillent sur Teldrassil, un Ancien du savoir et un Ancien de la Guerre tiennent leur place à Darnassus, et Onu, un autre Ancien du savoir, parle au nom de la forêt au Bosquet des Anciens, en Sombrivage." },
        { "Ils sont lents à parler et plus lents encore à changer d'avis. Un peuple qui a planté sa capitale dans un arbre, je suppose, apprend à écouter les arbres." },
      },
    },
    ["archesonus"] = {
      title = "Historienne royale Archesonus",
      text = {
        { "Vous m'avez donc trouvée. Je garde l'histoire de Forgefer depuis le Haut-Siège, à quelques pas du trône du roi Magni, et quiconque m'interroge à son sujet ferait bien d'avoir un après-midi devant lui." },
        { "L'histoire qu'on me demande le plus, c'est celle des Sombrefer. La guerre des Trois Marteaux s'acheva quand le thane-sorcier Thaurissan appela Ragnaros, et le réveil du seigneur du Feu réduisit leur propre pays en cendres. Des reliques gisent encore dans les ruines de Thaurissan, dans les Steppes ardentes, et elles en savent plus sur cette histoire que je n'ai pu en lire. Qui me rapportera ce qu'elles disent aura toute ma gratitude." },
        { "Ce registre est mon œuvre, $gvoyageur:voyageuse;, avec beaucoup d'aide de la Ligue des explorateurs, qui rapporte plus de choses qu'une seule historienne n'en pourrait lire. Si une page vous a bien servi, j'en suis heureuse. Si l'une d'elles vous a fait défaut, venez me le dire." },
        { side = "Horde", aside = true, sign = "P. F.", "Je ne l'ai jamais rencontrée. Son récit du monde reste le plus équitable que j'aie lu sous une plume vivante." },
      },
    },
    ["argent-dawn"] = {
      title = "L'Aube d'argent",
      text = {
        { "L'Aube d'argent recrute contre le Fléau dans l'Alliance comme dans la Horde. Ses chevaliers, ses prêtres et ses érudits demandent à un voyageur ce qu'il est prêt à combattre, plutôt que la bannière qu'il suit. Le seigneur Maxwell Tyrosus la dirige depuis la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est." },
        { "Des officiers au camp du Noroît et à la Barricade délivrent des commissions et acceptent les pierres du Fléau que portent les morts. Des émissaires travaillent à Hurlevent, à Darnassus et à Long-guet. L'Aube a fait de sa guerre une cause que les gens des deux factions peuvent rejoindre." },
        { "Elle partage un ennemi avec la Croisade écarlate, mais guère d'affection pour ses méthodes. L'Aube tient la méfiance de la Croisade envers chaque étranger pour une aide au roi-liche. L'objection a son bon sens : ce combat a déjà bien assez d'ennemis." },
      },
    },
    ["black-dragonflight"] = {
      title = "Le Vol draconique noir",
      text = {
        { "Neltharion était le Gardien de la Terre, chargé des profondeurs du monde. Sa trahison envers les autres vols draconiques lui valut le nom d'Aile de mort. Après la Deuxième Guerre, il entra dans les conseils des rois humains sous le nom de seigneur Prestor, cachant un dragon derrière un visage de noble. Il échappa aux Aspects après la lutte de Grim Batol ; on ignore toujours où il s'est retiré." },
        { "Ses enfants occupent des lieux que nous pouvons nommer. Onyxia garde sa couvée dans le marécage d'Âprefange. Nefarian tient le pic Rochenoire, commande ses orcs et élève au-dessus d'eux des dragons chromatiques. Des dragonnets noirs peuplent les Carmines et les Terres ingrates, tandis que des draconides gardent les plus grands domaines du vol." },
        { "Les repaires sont assez redoutables. Le seigneur Prestor a montré ce qu'un dragon noir pouvait accomplir avec un siège à la table d'un conseil." },
      },
    },
    ["blackrock-clan"] = {
      title = "Le clan Blackrock",
      text = {
        { "Les Blackrock étaient le plus grand clan de l'ancienne Horde. Leur chef Blackhand la mena comme chef de guerre pendant la Première Guerre, jusqu'à ce qu'Orgrim Doomhammer lui brise le crâne et prenne le titre, et Doomhammer était lui aussi un Blackrock. Quand la Horde tomba, la plupart du clan finit dans les camps comme tout le monde, et beaucoup de ceux qui en sortirent suivirent Thrall." },
        { "Pas tous. Les fils de Blackhand, Rend et Maim, rassemblèrent des survivants à l'intérieur du mont Rochenoire. Les fidèles de Rend gardent les anciennes coutumes : la conquête, la cruauté et le culte du chef de guerre. Rend se fait toujours appeler chef de guerre et n'a que mépris pour le nom de Thrall. Pire, il s'est allié aux dragons noirs qui nichent en haut du pic." },
        { "Depuis la montagne, le clan lance ses raids au nord et à l'ouest. Il tient les Steppes ardentes, il a pris le donjon de Guet-de-pierre dans les Carmines, et les gens de Comté-du-Lac vivent en vue de ses feux. Quoi que la Horde soit devenue en Durotar, voilà ce qu'elle était." },
      },
    },
    ["blood-elves"] = {
      title = "Les elfes de sang",
      text = {
        { "Après la chute de Quel'thalas, le dernier de sa lignée royale, le prince Kael'thas Sunstrider, mena ce qui restait des hauts-elfes dans la lutte de l'Alliance contre le Fléau. Ils se rebaptisèrent elfes de sang en l'honneur de leur peuple tombé. Coupés du Puits de soleil qui les avait nourris pendant des milliers d'années, ils découvrirent aussi à quel point ils avaient besoin de sa magie, et souffrirent de son manque." },
        { "Comme l'Alliance exigeait des batailles que ses forces affaiblies ne pouvaient gagner seules, Kael'thas accepta l'aide de dame Vashj et de ses nagas. Son commandant, Garithos, condamna les elfes de sang comme traîtres et les envoya à la mort. Vashj les libéra des cachots de Dalaran et les mena en Outreterre, le reste brisé du monde des orcs. Là, ils libérèrent Illidan Stormrage de sa geôlière, et Kael'thas se mit à son service en échange de la magie dont son peuple avait besoin." },
        { "Certains des siens sont bien plus proches. Des elfes de sang fouillent les falaises et les ruines d'Azshara à la recherche de la magie que les Bien-nés y ont laissée, et broient ce qu'ils trouvent en une poussière scintillante ; un gobelin qui a pris leur argent et une bande d'orcs qui leur a prêté des gardes ont tous deux appris ce que vaut leur emploi. Un autre est entré à Hache-tripes pour vider ses ruines de leur pouvoir. Gershala Nightwhisper, à Auberdine, craint qu'ils ne prennent le chemin des satyres et des nagas. Je crains qu'il n'ait raison." },
      },
    },
    ["bloodhoof-village"] = {
      title = "Sabot-de-Sang",
      text = {
        { "Le village de Sabot-de-Sang est le cœur des plaines, une ville de longues maisons et d'enclos à kodos sur la route entre le camp Narache et Thunder Bluff. Son chef est Baine Bloodhoof, fils du grand chef Cairne, et c'est ici que les jeunes passent le deuxième des rites, le rite de la Vision : ils boivent l'eau des voyants devant le feu du village et suivent là où la vision les mène." },
        { "C'est un endroit animé, accueillant et pratique. Les taurens de Sabot-de-Sang sont fermiers et éleveurs autant que chasseurs, et ils nourriront un étranger avant de lui demander ce qui l'amène." },
      },
    },
    ["blue-dragonflight"] = {
      title = "Le Vol draconique bleu",
      text = {
        { "Malygos, le Tisse-sort, reçut la garde de la magie, et son vol l'a payé cher. Quand Aile de mort se retourna contre les autres vols draconiques pendant la guerre des Anciens, le vol bleu souffrit plus que tous ; très peu survécurent, et Malygos n'a plus jamais été le même." },
        { "Leurs repaires dans ces contrées sont rares. Des draconiens bleus gardent les rives du lac Mennar, en Azshara, et les grottes de Mazthoril, au Berceau-de-l'Hiver, cachent un refuge où leur matrone protectrice, Haleh, reçoit ceux qui portent une écaille de dragon bleu et se tiennent sur la bonne rune. Les Aspects, vous dira-t-elle, exigent que leurs vols restent à l'écart des affaires des mortels. Elle vous dira aussi que les enfants d'Aile de mort rendent la chose difficile." },
        { "Azuregos monte sa propre garde sur les ruines du sud d'Azshara, en quête des trésors arcaniques que les Bien-nés ont laissés derrière eux. La côte est en ruine depuis dix mille ans, et donne encore du travail à un dragon bleu." },
      },
    },
    ["bolvar-fordragon"] = {
      title = "Généralissime Bolvar Fordragon",
      text = {
        { "Le généralissime Bolvar Fordragon commande les armées de Hurlevent et se tient aux côtés de l'enfant-roi, Anduin Wrynn, tandis que son père Varian a disparu. C'est un paladin de la vieille école, pieux, honnête et inébranlable, et il garde les soldats du royaume là où le royaume en a le plus besoin, ce qui est rarement là où les provinces les voudraient." },
        { "C'est un homme prudent, trop prudent peut-être. Quand le magistrat de Comté-du-Lac fit savoir que les orcs Blackrock avaient des dragons derrière eux, Bolvar refusa de déplacer des troupes sur une simple supposition et envoya le messager demander conseil à dame Katrana Prestor. Le maréchal Windsor, qui avait trouvé la preuve, le traita d'imbécile : elle se tenait à deux pas de lui, dit-il, et il ne la voyait pas. Quand Windsor démasqua la dame dans la salle du trône comme étant Onyxia, fille d'Aile de mort, il déclara que même le généralissime avait été sa marionnette, tenu par un médaillon de dragon. À la fin, ce fut Bolvar qui resta avec le médaillon brisé entre les mains." },
        { "Ce n'est pas un imbécile. C'est un honnête homme qui a cru une dragonne sur parole, et je doute qu'il recommence." },
      },
    },
    ["brill"] = {
      title = "Brill",
      text = {
        { "Brill était une paisible ville de fermiers sur la route à l'est du Glas, et les Réprouvés en ont fait la leur : l'hôtel de ville abrite un magistrat, la taverne des Pendus sert ses étranges boissons à d'étranges clients, et dans sa cave les Gardes noirs gardent leurs prisonniers, des montagnards nains parmi eux, en attendant de s'en occuper." },
        { "C'est aussi là que la Société royale des apothicaires fait une bonne part de son travail. Je n'en dirai pas plus, sinon qu'un nain ne devrait pas accepter de boisson à Brill." },
      },
    },
    ["bronze-dragonflight"] = {
      title = "Le Vol draconique de bronze",
      text = {
        { "Nozdormu, l'Intemporel, reçut la garde du temps, et son vol en surveille les chemins. On les voit rarement. Quand on les voit, c'est d'ordinaire parce que quelque chose ne va plus dans le moment où les choses arrivent." },
        { "À Andorhal, l'un d'eux se promène sous les traits d'une étrange petite gnome appelée Chromie, et a fait d'une pièce de l'auberge en ruine un lieu qui n'appartient pas tout à fait au reste de la ville. Elle dit que le Fléau a trafiqué le temps à cet endroit ; elle chasse les parasites qui se nourrissent de ses fils rompus, et elle a aidé un voyageur à changer le sort d'un homme tombé à Comté-de-Darrow." },
        { "En Tanaris, près des Grottes du temps, attend Anachronos, qui était au Mur du scarabée il y a mille ans, quand on le scella. Le vol de bronze se souvient de la guerre contre Ahn'Qiraj parce qu'il l'a livrée. Demandez-leur ce qu'ils savent de demain, $gvoyageur:voyageuse;, et ils vous répondront avec un sourire que vos plus grands exploits sont encore à venir." },
      },
    },
    ["burning-blade"] = {
      title = "La Lame ardente",
      text = {
        { "La Lame ardente fut jadis un clan orc, célèbre pour ses maîtres-lames, et certains de ces maîtres-lames se sont libérés des démons et servent encore Thrall. Le reste du nom est passé à un culte. La Lame ardente d'aujourd'hui est une confrérie de démonistes et de fanatiques qui vénèrent les démons ayant jadis asservi leur peuple, et qui répondent au Conseil des ombres, celui-là même qui amena la Horde dans ce monde." },
        { "Ils sont la honte de la Horde, cachée sur ses propres terres. Ils tiennent les grottes du Rocher du crâne en Durotar, en vue d'Orgrimmar, et le pic de Brume-funeste dans les Tarides, où un gangregarde veille sur une graine démoniaque, un lien avec la Légion elle-même ; en Désolace, ils ont fait leur la forteresse de Hache-Tonnerre, et dans les gouffres sous Orgrimmar même, une branche qui se fait appeler la Lame brûlante complote dans le noir. Le peuple de Thrall les traque partout où il les trouve." },
        { "Ils ont été plus près que quiconque n'aime l'admettre de déclencher une nouvelle guerre. Quelques années après le mont Hyjal, un démon mineur du nom de Zmodlor prit le culte en main et dressa Durotar et Theramore l'un contre l'autre : des navires attaqués, des raids imputés à l'autre camp, un traître murmurant dans le conseil de chaque chef, dont le propre chambellan de dame Jaina Proudmoore. Jaina et Thrall découvrirent tout cela ensemble, et la paix tint. Le culte n'en avait pas fini, comme le Rocher du crâne vous le dira." },
      },
    },
    ["burning-legion"] = {
      title = "La Légion ardente",
      text = {
        { "La Légion ardente est une armée de démons, rassemblée sur mille mondes conquis par le titan déchu Sargeras, et elle est venue trois fois pour le nôtre : une fois il y a dix mille ans, par le Puits d'éternité des elfes de la nuit ; une fois par les orcs, que ses serviteurs corrompirent et envoyèrent par la Porte des Ténèbres ; et une fois pendant la dernière guerre, quand son général Archimonde tomba au pied de l'Arbre-Monde, sur le mont Hyjal." },
        { "Elle n'est jamais tout à fait partie. Le seigneur Kazzak tient les Terres foudroyées avec une armée de démons autour de la Porte des Ténèbres endormie. Les démonistes du Conseil des ombres gardent des démons à Jaedenar, en Gangrebois, où toute la forêt a pourri autour d'eux. Gardes funestes et infernaux arpentent le canyon de la Malechute en Ashenvale, où Grom Hellscream tua Mannoroth, le convent de Mannoroc en Désolace, et les ruines d'Azshara." },
        { "La Légion est patiente. Elle a perdu trois guerres et elle est toujours là, et je ne crois pas qu'elle en ait fini avec nous." },
      },
    },
    ["cairne-bloodhoof"] = {
      title = "Cairne Bloodhoof",
      text = {
        { "Cairne Bloodhoof est le grand chef des taurens, chef de la tribu Bloodhoof, et le plus vieil ami que la Horde ait en Kalimdor. Quand les orcs de Thrall touchèrent terre, il menait son peuple à travers les plaines, les centaures sur les talons, et les orcs se battirent à leurs côtés. Cairne les remercia par son amitié et ses conseils, et les taurens font partie de la Horde depuis lors." },
        { "Il est très vieux aujourd'hui, et très grand, et il parle lentement et rarement. Il a bâti Thunder Bluff, y a rassemblé les tribus et donné aux taurens un foyer pour la première fois de mémoire tauren. Son fils Baine tient le village de Sabot-de-Sang, et fut un jour, dit-on, enlevé par les centaures et ramené par un maître des bêtes de la Horde." },
        { "Les orcs le vénèrent, et l'Alliance lui fait davantage confiance qu'à aucun autre chef de la Horde. Les uns comme les autres, je crois, ont raison." },
      },
    },
    ["camp-narache"] = {
      title = "Le camp Narache",
      text = {
        { "Le camp Narache se trouve sur la mesa de Nuage rouge, au sud de Mulgore, un cercle de tentes de peau et de totems autour d'un feu, et c'est là que les jeunes taurens commencent. Le chef Hawkwind et sa famille tiennent le camp, et ils imposent aux jeunes le premier des rites de la Terre-Mère : le rite de la Force, à prouver contre les hurans qui se sont glissés dans le ravin en contrebas." },
        { "C'est d'abord un camp de chasse. Les taurens chassent par besoin et par plaisir, et on attend d'un jeune tauren qu'il rapporte plumes et viande avant que quiconque lui demande ce qu'il sait faire d'autre." },
      },
    },
    ["cenarion-circle"] = {
      title = "Le Cercle cénarien",
      text = {
        { "Le Cercle cénarien est la confrérie des druides, nommée d'après le demi-dieu Cénarius, qui instruisit les premiers d'entre eux. Son fondateur fut Malfurion Stormrage, qui mena les elfes de la nuit contre la Légion ardente il y a dix mille ans et a aujourd'hui disparu ; ses frères druides ignorent ce qu'il est devenu. Pendant la plus grande partie de son histoire, le Cercle fut un ordre d'elfes de la nuit ; les taurens y ont désormais eux aussi leurs druides, et l'archidruide Hamuul Runetotem les représente à Thunder Bluff." },
        { "Son siège est Havrenuit, à Reflet-de-Lune, sous la garde de Remulos, fils de Cénarius, et l'Alliance comme la Horde peuvent s'y promener en paix. Il tient des postes partout où la nature est blessée : au pic des Serres-Rocheuses, dans les bois empoisonnés de Gangrebois, et au Fort cénarien, en Silithus, d'où il surveille les ruches des insectes et les murs d'Ahn'Qiraj." },
        { "Les druides ont une patience qui dépasse l'entendement de n'importe quel nain, et ils pensent en saisons et en siècles. Quand le Cercle dit que quelque chose ne va pas, les sages écoutent." },
      },
    },
    ["cenarius"] = {
      title = "Cénarius",
      text = {
        { "Cénarius était le seigneur des forêts, un demi-dieu au corps de cerf sous la taille et aux bois ramifiés, et le premier maître des elfes de la nuit. Bien avant la Fracture, il se prit d'affection pour leur jeunesse curieuse et lui enseigna les voies du monde vivant. Malfurion Stormrage fut son plus grand élève, et le druidisme est ce qu'ils firent naître à eux deux." },
        { "Il combattit la Légion pendant la guerre des Anciens, à la tête des anciens de la forêt contre les démons, survécut à la Fracture et aida Malfurion à enfermer Illidan. Ensuite, il resta à Reflet-de-Lune, sur le mont Hyjal. Ses fils, les Gardiens du bosquet, veillèrent sur les elfes de la nuit pendant que les druides dormaient, et ses filles, les dryades, osèrent de plus en plus se montrer." },
        { "Pendant la Troisième Guerre, il sortit de la forêt pour chasser d'Ashenvale les orcs de Grom Hellscream, et les orcs, fous de sang de démon, le tuèrent. Ses enfants arpentent toujours les bois de Kalimdor, de Raynebois aux Serres-Rocheuses, et Remulos garde Reflet-de-Lune en son nom. La mémoire d'un gardien est longue. Je n'aborderais pas le sujet des orcs avec l'un d'eux." },
      },
    },
    ["centaurs"] = {
      title = "Les centaures",
      text = {
        { "Les centaures descendent de Zaetar, un fils de Cénarius, et de Theradras, une princesse de la terre élémentaire. Ils tuèrent leur père ; leur mère l'ensevelit à Maraudon. Ses enfants gardent toujours le tombeau comme une terre sacrée." },
        { "Parmi leurs clans, on compte les Kolkar des Tarides et de Désolace, les Gelkis et les Magram, rivaux, les Galak de Mille pointes et les Maraudine, au tombeau. Pendant des générations, ils pourchassèrent les taurens à travers les plaines de Kalimdor, jusqu'à ce que Cairne et ses alliés orcs les repoussent." },
        { "Les clans continuent leurs raids. Apprenez leurs noms autant que le bruit de leurs sabots, $gvoyageur:voyageuse;. Leurs querelles comptent pour ceux qui essaient de vivre à portée de leurs camps." },
      },
    },
    ["church-of-the-holy-light"] = {
      title = "L'Église de la Lumière sacrée",
      text = {
        { "L'Église de la Lumière sacrée enseigne que la vertu, la compassion et le sacrifice puisent à une puissance capable de guérir et de protéger. La foi est venue de Lordaeron vers le sud, et la cathédrale de la Lumière de Hurlevent en est aujourd'hui le siège, sous l'autorité de l'archevêque Benedictus. Les nains aussi ont appris ses voies auprès de leurs voisins humains." },
        { "Pendant la Deuxième Guerre, l'archevêque Alonsus Faol fonda les chevaliers de la Main d'argent. Ces premiers paladins, menés par Uther le Porteur de lumière, portèrent la Lumière sur le champ de bataille avec leurs épées. Depuis la chute de Lordaeron, Hurlevent est devenue le centre de l'Église, et ses prêtres et paladins servent dans toute l'Alliance." },
        { "Les questions de foi peuvent occuper un érudit pendant des années. Un voyageur blessé a une raison plus immédiate d'être reconnaissant du savoir d'un prêtre." },
      },
    },
    ["coldridge-valley"] = {
      title = "Vallée des Frigères",
      text = {
        { "Courbenclume rassemble les recrues naines et gnomes dans la vallée des Frigères, au sud de Kharanos. Elles y trouvent leurs instructeurs, leurs premiers ordres, et la passe qui les mènera au-delà, dans Dun Morogh. Un début modeste, peut-être, mais toute route en a un." },
        { "Ces ordres ne se limitent pas à l'entraînement. Les troggs Mâcheroc menacent la vallée, les trolls Frostmane ont établi un camp tout près, et Balir Frosthammer et Grelin Whitebeard ont besoin d'aide contre eux. Gardez votre arme à portée de main, $gvoyageur:voyageuse;. On a besoin des recrues avant même qu'elles aient quitté la vallée." },
      },
    },
    ["cult-of-the-damned"] = {
      title = "Le Culte des damnés",
      text = {
        { "Kel'Thuzad était un archimage de Dalaran et un membre de son conseil dirigeant, et il chercha des choses interdites dans les arts nécromantiques jusqu'à ce que quelque chose lui réponde : le roi-liche. Kel'Thuzad quitta le Kirin Tor, alla parmi les pauvres et les désespérés de Lordaeron, et leur promit un monde sans rois ni faim. Ils devinrent le Culte des damnés, et ils le crurent." },
        { "L'œuvre du culte fut la peste. Ses membres contaminèrent les greniers d'Andorhal et des villages du nord, et les morts se levèrent partout où l'on mangea ce grain. Le prince Arthas tua Kel'Thuzad à Andorhal, mais le roi-liche avait besoin de lui, et il revint sous la forme d'une liche. La maison Barov livra au culte son château de Caer Darrow, et dans ses caves ils tiennent leur école de nécromancie, la Scholomance." },
        { "Ce sont des hommes et des femmes vivants, ce que je trouve pire que les morts. Une goule n'a pas le choix de ce qu'elle sert. Les nécromanciens du culte, eux, ont choisi." },
      },
    },
    ["daelin-proudmoore"] = {
      title = "Daelin Proudmoore",
      text = {
        { "Daelin Proudmoore, grand amiral de Kul Tiras, fut un héros de la Deuxième Guerre : il commanda les flottes de l'Alliance aux côtés d'Anduin Lothar et d'Uther le Porteur de lumière, et il ne pardonna jamais aux orcs. Il avait aussi une fille, Jaina, partie étudier la magie à Dalaran." },
        { "Il quitta Lordaeron avec sa flotte avant qu'Arthas ne la détruise, cherchant des survivants sur les mers, et après bien des mois trouva Kalimdor, et sa fille, en paix avec la Horde. Il ne voulut pas l'accepter. Il débarqua ses soldats de marine sur la côte de Durotar, éleva ce donjon, et entreprit de détruire les orcs avant qu'ils ne prennent racine." },
        { "Jaina dut choisir entre son père et la paix, et elle choisit la paix. Daelin mourut dans les combats avant qu'ils aient pu se réconcilier. Sa flotte gît en épave au large de cette plage, et quelques-uns de ses hommes tiennent encore le donjon, au milieu d'une terre qui porte le nom d'un orc." },
      },
    },
    ["dark-iron-dwarves"] = {
      title = "Les nains Sombrefer",
      text = {
        { "Le troisième des trois marteaux, et celui qui n'a jamais pardonné. Depuis que les Sombrefer ont perdu leur guerre contre Forgefer, et réveillé Ragnaros dans leur fureur, ils vivent dans le mont Rochenoire sous leur empereur, Dagran Thaurissan, au service du seigneur du Feu qu'ils ont invoqué." },
        { "Ils n'y sont pas restés. Leurs esclaves creusent le Chaudron dans la gorge des Vents brûlants, leurs fouilleurs d'Ombreforge pillent les ruines d'Uldaman et tiennent la forteresse d'Angor dans les Terres ingrates, leurs espions rôdent en Dun Morogh et leurs pillards harcèlent le Loch Modan. Dans les Paluns, ils ont fait un vrai mal : ils ont pris la forteresse de Dun Modr et brisé le viaduc de Thandol, le grand pont vers le nord." },
        { "Un Sombrefer se bat avec le feu, la poudre noire et une rancune vieille de deux siècles. Ne lui tournez jamais le dos." },
      },
    },
    ["darkspear-trolls"] = {
      title = "Les trolls Darkspear",
      text = {
        { "Les Darkspear sont des trolls de la jungle apparentés aux Gurubashi de Strangleronce. Quand la flotte de Thrall atteignit leurs îles en route vers Kalimdor, la tribu combattait des murlocs et leur sorcière des mers. Les orcs se battirent à leurs côtés. Le chef Sen'jin mourut, et les Darkspear survivants suivirent Thrall par-delà la mer." },
        { "Vol'jin les mène aujourd'hui depuis Orgrimmar, près du chef de guerre. Leurs chasseurs, leurs chamans et leurs féticheurs servent dans toute la Horde, et gardent les anciens loas des trolls tout en se faisant un foyer parmi de nouveaux alliés." },
      },
    },
    ["darnassus"] = {
      title = "Darnassus",
      text = {
        { "Darnassus se dresse dans la cime de Teldrassil, une nouvelle capitale bâtie après la Troisième Guerre. Le clair de lune, les cascades et l'éclat du temple de la Lune emplissent une cité aux murs rares et aux salles poussées parmi les branches. Un nain de Forgefer est habitué à avoir un peu plus de pierre au-dessus de la tête." },
        { "Les elfes de la nuit ont rejoint l'Alliance et ouvert cette cité à des visiteurs de peuples qu'ils ont longtemps tenus à l'écart. Tyrande Whisperwind dirige les prêtresses depuis le Temple, tandis que Fandral Staghelm guide les druides depuis l'Enclave cénarienne. Retenez ces deux lieux, $gvoyageur:voyageuse;. Une bonne partie des affaires de la cité commence dans l'un ou dans l'autre." },
      },
    },
    ["deathknell"] = {
      title = "Le Glas",
      text = {
        { "Le Glas est une crypte et un village en ruine à la lisière ouest de Tirisfal, et c'est là que les Réprouvés s'éveillent. Les morts de Lordaeron qui se relèvent maîtres de leur esprit sont amenés ici, et le gardien de la crypte les accueille par les mots dont chacun d'eux se souvient : vous n'êtes plus l'esclave du roi-liche." },
        { "Tous ceux qui se relèvent n'ont pas cette chance. Le nord du village est plein de morts sans esprit, qui appartiennent toujours au roi-liche, et le premier devoir des Réprouvés tout juste éveillés est de les détruire : leurs anciens frères et sœurs, comme le leur rappellent les prêtres des ombres de la chapelle." },
      },
    },
    ["deathstalkers"] = {
      title = "Les Traqueurs noirs",
      text = {
        { "Les Traqueurs noirs sont les yeux et les couteaux des Réprouvés : la garde d'élite du seigneur Varimathras, comme le dit l'un de leurs recruteurs, envoyée en avant des armées de la Dame noire pour voir ce qui les attend. On les croise partout où les Réprouvés repoussent leurs frontières : en éclaireurs dans les fermes du nord de la forêt des Pins argentés, dans le donjon d'Ombrecroc pour surveiller Arugal, sur les collines au-dessus de Hautebrande, ou à recueillir pour Nathanos les rapports des Maleterres." },
        { "On ne les rejoint pas en le demandant. Les recrues prouvent leur valeur, et leur discrétion, dans les arrière-salles de Fossoyeuse ; l'une de ces missions a révélé que le Syndicat, les seigneurs déchus d'Alterac, avait un ami parmi les marchands de la cité. Avec la bénédiction de Varimathras, se vante l'un d'eux, leurs rangs grossissent." },
        { "Ils ne sont pas tous aussi sinistres que leur nom. Rane et Quinn Yorick sont frères, et Rane, alors que Quinn se remet à peine des griffes d'une goule, veut que leur rapport soit remis avant toute chose. Morts, mais toujours zélés. Les Réprouvés sont pleins de surprises." },
      },
    },
    ["deeprun-tram"] = {
      title = "Le Tram des profondeurs",
      text = {
        { "Le Tram des profondeurs transporte ses passagers entre Forgefer et Hurlevent sur des plates-formes mobiles, sous la terre. Il a réduit un voyage de plusieurs jours à une affaire de minutes. Même un nain qui aime marcher sait apprécier une telle prouesse." },
        { "Le tunnel donne à notre amitié avec Hurlevent une forme bien concrète : deux capitales reliées par une voie qui épargne à leurs voyageurs la longue route par la surface. L'ingéniosité gnome a sauvé bien des paires de bottes." },
        { "Surveillez les vitres là où le tunnel passe sous l'eau, $gvoyageur:voyageuse;. Certains passagers disent avoir vu quelque chose de très grand les regarder en retour. Vous devriez avoir le temps d'y jeter un œil avant que la plate-forme ne vous emporte." },
      },
    },
    ["defias-brotherhood"] = {
      title = "La Confrérie défias",
      text = {
        { "Quand les orcs rasèrent Hurlevent pendant la Première Guerre, ce fut la guilde des Tailleurs de pierre, sous un maître nommé Edwin VanCleef, qui la rebâtit. Le travail achevé, la Chambre des nobles refusa de les payer. VanCleef mena ses maçons dans une émeute à travers les rues neuves, et quitta la cité en jurant vengeance." },
        { "La guilde devint une bande. Dans la Marche de l'Ouest, ils prirent le nom de Confrérie défias, nouèrent des foulards rouges sur leurs visages, et entreprirent de ruiner les terres agricoles qui nourrissent la cité : brûler les champs, chasser les familles, et s'allier à quiconque voulait d'eux. Des ingénieurs gobelins travaillent pour eux dans les Mortemines, et leur influence s'étend jusqu'à Elwynn, aux Carmines, au Bois de la Pénombre et jusqu'à la prison de la cité, où Bazil Thredd, le lieutenant de VanCleef, a soulevé les détenus." },
        { "Les maçons avaient un grief, pour leur travail impayé. Mais quoi que la Confrérie ait pu défendre un jour, les fermiers de la Marche de l'Ouest l'ont payé bien plus cher que n'importe quel seigneur de Hurlevent." },
      },
    },
    ["dolanaar"] = {
      title = "Dolanaar",
      text = {
        { "Dolanaar se trouve sur la route de Sombrevallon à Darnassus, rassemblé autour d'un puits de lune, avec une auberge et des bâtisses parmi les arbres. Druides et Sentinelles y travaillent au plus près des ennuis de la forêt. C'est une halte utile avant de poursuivre vers la capitale." },
        { "Ces derniers temps, leurs soucis comprennent les furbolgs Pin-tordu, des satyres dans les grottes et des créatures malades dans les bois. L'air paisible du village ne dit pas grand-chose de ce travail. Écoutez ce que ses gardiens vous demandent ; ils ont vu changer le pays autour d'eux." },
      },
    },
    ["dragons-of-nightmare"] = {
      title = "Les dragons du Cauchemar",
      text = {
        { "Les dragons verts d'Ysera gardent le Rêve d'émeraude, le monde intact que parcourent les druides endormis. Quatre lieutenants veillaient sur ses grands arbres-portails : Ysondre, Léthon, Emeriss et Taerar, postés au Bois de la Pénombre, dans les Hinterlands, en Feralas et en Ashenvale." },
        { "Le Cauchemar les a pris. Ils en ressortent déformés et attaquent ceux qui approchent. Emeriss répand la pourriture, Taerar se divise en ombres, et Léthon arrache les esprits des morts. Remulos rassemble des fragments de corruption pris aux portails pour les étudier. Un voyageur qui atteint l'un de ces arbres risque de découvrir que le gardien même qui aurait dû le rendre sûr en est devenu le danger." },
      },
    },
    ["dreadlords"] = {
      title = "Les seigneurs de l'effroi",
      text = {
        { "Les seigneurs de l'effroi, les nathrezim, sont les intrigants de la Légion ardente : vampiriques, patients, plus doués pour corrompre que pour conquérir. Kil'jaeden les chargea de garder sa création la plus dangereuse, le roi-liche. Tichondrius, le plus rusé d'entre eux, se délectait de la peste ; Mal'Ganis attendait le prince Arthas à Stratholme ; Anetheron combattit aux côtés d'Archimonde sur le mont Hyjal." },
        { "Quand le pouvoir du roi-liche faiblit, ses geôliers tentèrent de prendre Lordaeron pour eux-mêmes. Ils la perdirent au profit de Sylvanas et de ses Réprouvés, qui bâtirent leur cité sous la capitale en ruine. Varimathras y sert désormais la Dame noire, que cela lui plaise ou non. Balnazzar porte le visage du chef même de la Croisade écarlate, à Stratholme." },
        { "Un seigneur de l'effroi vous montre rarement ce qu'il est. Si quelqu'un en position d'autorité semble tenir à ce que les vivants et les morts continuent de s'entretuer, $gvoyageur:voyageuse;, demandez-vous à qui cela profite." },
      },
    },
    ["druids"] = {
      title = "Druides",
      text = {
        { "Le premier druide fut Malfurion Stormrage, instruit par le demi-dieu Cénarius avant la guerre des Anciens. Après la destruction du Puits, les elfes de la nuit qui avaient renoncé aux arcanes le suivirent, et pendant des milliers d'années les druides dormirent dans le Rêve d'émeraude, ne s'éveillant que lorsque le monde avait besoin d'eux." },
        { "Ils s'éveillent aujourd'hui, et ce ne sont plus seulement des elfes de la nuit : les taurens ont leurs propres druides, et les uns comme les autres répondent au Cercle cénarien, à Reflet-de-Lune. Un druide prend les formes du monde sauvage, entre autres l'ours, le félin et le phoque, soigne par la magie verte du Rêve et fait tomber la lune et les étoiles sur ses ennemis." },
        { client = "forever", "Des druides éolides exercent désormais des deux côtés de la querelle entre l'Alliance et la Horde." },
        { "Malfurion lui-même est parti dans le Rêve et n'en est pas revenu. Malgré tout le travail du Cercle dans le monde éveillé, son plus grand maître reste hors de portée d'un messager ordinaire." },
      },
    },
    ["druids-of-the-talon"] = {
      title = "Les druides de la Serre et de la Griffe",
      text = {
        { "Les druides de Malfurion n'ont jamais formé un seul ordre. Certains prirent la forme du grand ours et devinrent les druides de la Griffe ; d'autres prirent la forme du corbeau-tempête et devinrent les druides de la Serre. Les uns comme les autres respectèrent le pacte conclu avec Ysera et dormirent des siècles durant dans les refuges des saisons tandis que leur esprit parcourait le Rêve d'émeraude, et pendant la Troisième Guerre, Malfurion les réveilla pour combattre." },
        { "Certains dorment encore. Dans le refuge des saisons de Ban'ethil, sur Teldrassil, les druides de la Serre hibernent sous la garde d'un grand gardien. Les furbolgs Pin-tordu y sont entrés par effraction, et l'un d'eux, Ursal le Mutileur, a tant troublé l'appel des dormeurs qu'ils risquent de ne jamais se réveiller. Un druide de la Griffe perdu dans le même refuge a vu son propre corps se retourner contre lui." },
        { "Ils ne sont pas toujours faciles à réveiller. Kerlonian Evershade, un druide de la Griffe tout juste revenu du Rêve, somnole volontiers au bord de la route en Sombrivage, et demande qu'on le réveille avec son cor s'il s'assoupit en chemin. Dix mille ans, c'est long pour avoir été fatigué." },
      },
    },
    ["dun-morogh"] = {
      title = "Dun Morogh",
      text = {
        { "Dun Morogh, ce sont les hautes terres enneigées autour de Forgefer, patrie des nains du clan Bronzebeard et de leurs voisins gnomes." },
        { "Ces terres sont à nous, mais nous les partageons, et pas toujours de bon gré. Les trolls Frostmane tiennent les collines de l'ouest, les troggs creusent où bon leur semble, et depuis la chute de Gnomeregan les gnomes sont nos voisins dans leurs propres vallées autant que dans notre cité." },
        { "Apprenez bien ses routes, $gvoyageur:voyageuse;. La plupart des nains que vous rencontrerez un jour y ont fait leurs premiers pas." },
      },
    },
    ["durotar"] = {
      title = "Durotar",
      text = {
        { "Durotar est un pays dur : terre rouge, roche rouge, épines et scorpions, brûlé par le soleil et entaillé de canyons secs, avec la mer d'un côté et les longues plaines des Tarides de l'autre. Les orcs l'ont choisi malgré tout. Thrall lui a donné le nom de son père, Durotan, chef du clan Loup-de-Givre, assassiné avant que son fils ait pu le connaître." },
        { "La Horde est venue ici après la dernière guerre, après avoir traversé la mer depuis les camps de Lordaeron et combattu aux côtés des elfes de la nuit et des hommes au mont Hyjal. On ne l'y laissa pas longtemps en paix : l'amiral Daelin Proudmoore, de Kul Tiras, le père de Jaina Proudmoore, lança sa flotte contre les orcs, et fut vaincu. Depuis, les orcs ne cessent de bâtir : Orgrimmar au nord, Tranchecolline sur la route, le village de Sen'jin pour leurs alliés trolls." },
        { "Ils n'ont pas fini de nettoyer le pays. Les centaures lancent des raids depuis l'ouest, les hurans tiennent le sud, et dans les grottes du Rocher du crâne, en vue de la capitale, la Lame ardente vénère les démons qui asservirent jadis les orcs. Durotar est jeune, et le sait." },
      },
    },
    ["dwarves"] = {
      title = "Les nains de Forgefer",
      text = {
        { "Les nains tiennent le Khaz Modan depuis Forgefer depuis avant que quiconque ait mis leur histoire par écrit, et longtemps, ils n'ont pas su non plus d'où ils venaient. Les disques que la Ligue a rapportés d'Uldaman suggèrent une réponse dont les érudits débattent encore : les premiers nains auraient été des terrestres, façonnés dans la pierre par les Titans, qui avec le temps devinrent chair." },
        { "Trois clans partageaient jadis la montagne sous un même haut roi. À sa mort, ils se firent la guerre pour son trône ; les Bronzebeard gardèrent Forgefer, les Wildhammer partirent au nord et les Sombrefer réveillèrent le seigneur du Feu au sud. C'est le roi Magni Bronzebeard qui règne aujourd'hui. Son frère Muradin est parti au nord avec le prince de Lordaeron et on ne l'a pas revu depuis, et son frère Brann parcourt le monde pour la Ligue, ce qui est à peu près là où nous nous attendons à le trouver." },
        { "C'est un peuple solide, prudent et généreux, qui entretient ses rancunes aussi bien que ses ouvrages de pierre, et je le dis avec affection. Si un nain vous dit qu'un pont tiendra, $gvoyageur:voyageuse;, il tiendra. Si un nain vous dit que la bière est bonne, faites-vous votre propre idée." },
      },
    },
    ["earth-mother"] = {
      title = "La Terre-Mère",
      text = {
        { "Les taurens vénèrent la Terre-Mère comme la source du monde et de sa vie. Leurs traditions enseignent le respect des dons de la terre et le soin d'éviter le gaspillage. Les chamans parlent avec ses esprits, les voyants suivent des visions, et les ancêtres restent mêlés à la vie de ceux qui viennent après eux." },
        { "Les jeunes taurens accomplissent les rites de la Terre-Mère avant que les anciens de Thunder Bluff ne les acceptent. La Force se prouve contre les ennemis de la tribu. La Vision vient par l'eau des voyants et par ce qui apparaît dans le feu. La Sagesse exige la bénédiction des ancêtres aux Rochers rouges. Le voyage s'achève devant le grand chef." },
        { "Intéressez-vous aux rites si vous voulez comprendre vos hôtes, $gvoyageur:voyageuse;. La chasse, la mémoire et la terre se rejoignent dans la façon dont un jeune tauren gagne sa place parmi eux." },
      },
    },
    ["earthen"] = {
      title = "Les terrestres",
      text = {
        { "Les terrestres étaient les tailleurs de pierre des Titans, faits de roche vivante pour sculpter les profondeurs du monde. Quand les Titans partirent, ils continuèrent de façonner et de garder ces profondeurs, sans guère se soucier de ce qui se passait au-dessus. La Fracture les blessa comme elle blessa la terre elle-même. Ils perdirent beaucoup de ce qu'ils avaient été et s'enfermèrent dans les chambres fortes où ils avaient été créés : Uldaman, Uldum, Ulduar, comme les nomme le livre de notre bibliothèque." },
        { "Après près de huit mille ans, les terrestres d'Uldaman s'éveillèrent. Ils trouvèrent leur peau de pierre adoucie en chair et leur pouvoir sur la roche affaibli ; ils étaient devenus mortels. Ils se nommèrent nains, sortirent dans le monde éveillé, et fondèrent un royaume sous la plus haute montagne du pays, le Khaz Modan, la montagne de Khaz'goroth, autour d'une forge élevée en son honneur." },
        { "Tous ne s'éveillèrent pas. Des terrestres montent encore la garde dans les salles d'Uldaman, et chaque expédition que la Ligue y envoie les rencontre. Ils ne semblent pas savoir de qui nous sommes parents." },
      },
    },
    ["earthen-ring"] = {
      title = "Le Cercle terrestre",
      text = {
        { "Le Cercle terrestre est un cercle de chamans voué à l'étude et à la préservation des éléments. Ils ont oublié plus de choses sur les étranges anciens dieux, les vieilles légendes et le savoir d'autrefois que la plupart des érudits n'en apprendront jamais, dit un éclaireur de la Horde en Ashenvale, et quand surgit des éléments quelque chose que personne ne sait expliquer, c'est à eux qu'on l'apporte." },
        { "Ils se tiennent en marge des choses : un chaman à l'avant-poste de Zoram'gar, sur la côte d'Ashenvale, étudie ce que la mer rejette de Brassenoire ; un autre à l'Espoir de Lumière, là où les morts se pressent le plus. On a dit leurs intentions pures, même parmi ceux qui doutent de leurs fréquentations ; le Cercle a jadis tendu la main aux Réprouvés, et certains à Thunder Bluff se demandent aujourd'hui si c'était bien sage." },
        { "Une société savante qui répond aux éléments plutôt qu'à un roi. La Ligue reconnaît le genre, et l'envie un peu." },
      },
    },
    ["echo-isles"] = {
      title = "Les îles de l'Écho",
      text = {
        { "Les îles de l'Écho devaient être le nouveau foyer des trolls Darkspear, un chapelet d'îles couvertes de jungle au large de la côte de Durotar, très semblables à celles qu'ils avaient quittées. Un féticheur du nom de Zalazane en a décidé autrement. Il s'est tourné vers des magies noires, a envoûté son propre peuple et l'a plié à sa volonté, et les Darkspear restés fidèles ont dû fuir les îles pour le continent." },
        { "Zalazane règne toujours sur les îles, et de là il envoie ses trolls asservis par-delà les eaux pour attirer d'autres membres de la tribu sous son emprise. Ses victimes ne trouvent pas toujours le repos en mourant : l'âme de certaines, disent les trolls, est prisonnière de leur propre crâne, dans un cercle de pouvoir sur la plus grande des îles." },
      },
    },
    ["eitrigg"] = {
      title = "Eitrigg",
      text = {
        { "Eitrigg conseille Thrall à Orgrimmar, un vieux guerrier dont la Horde nouvelle a encore besoin du savoir. Quand le chef de guerre Goretooth apprit que Rend Blackhand vivait, il envoya des aventuriers consulter Eitrigg au sujet des Blackrock." },
        { "Les rivalités entre chefs de la Horde avaient coûté à Eitrigg ses fils et l'avaient éloigné de ses guerres. Vivant seul près d'Âtreval, il combattit Tirion Fordring, puis sauva le paladin d'une tour qui s'effondrait. Tirion le défendit plus tard, au prix de son rang dans la Main d'argent." },
        { "Pendant l'attaque de Thrall sur Stratholme, Tirion libéra Eitrigg. Devant la cité, Thrall lui demanda de l'aider à rendre à la Horde ses anciennes coutumes, et il accepta." },
      },
    },
    ["elune"] = {
      title = "Elune",
      text = {
        { "Elune est la déesse de la lune et la plus ancienne foi des elfes de la nuit. Avant la Fracture, ils croyaient qu'elle dormait le jour dans les profondeurs du Puits d'éternité et s'éveillait avec la nuit. Ses prêtresses gardaient alors ses temples, et les gardent aujourd'hui encore, au temple de la Lune, à Darnassus." },
        { "Elle leur répond. Les elfes de la nuit doivent à sa grâce, disent-ils, d'avoir survécu à la Fracture, et une grande prêtresse d'Elune, Tyrande Whisperwind, les guide depuis dix mille ans. Ses puits de lune abreuvent leurs villes, et ses prêtresses soignent par sa lumière ; au combat, m'a-t-on dit, elles savent la faire tomber sous une forme bien moins douce." },
        { "Une elfe de la nuit vous imposera rarement sa déesse. Son peuple a eu tout le temps d'apprendre la patience envers la foi des autres, et envers les autres tout court." },
      },
    },
    ["elwynn-forest"] = {
      title = "Forêt d'Elwynn",
      text = {
        { "Elwynn est la forêt qui nourrit Hurlevent : de grands arbres anciens, des prairies ouvertes, des fermes et des vignes, et la lente rivière qui descend vers la Marche de l'Ouest. C'est la contrée la plus douce des terres humaines, et il est difficile, en parcourant ses routes un matin d'été, de croire ce qui s'est passé ici." },
        { "Pendant la Première Guerre, les orcs sont passés par ces bois. Ils ont brûlé les fermes, l'abbaye et les villages l'un après l'autre, puis ils ont pris la cité elle-même. Le royaume a été rebâti après la Deuxième Guerre, et les bois abritent de nouveau des fermes et des villages." },
        { "La paix est plus mince qu'il n'y paraît. Les kobolds ont pris les mines, les gnolls Rivepatte lancent leurs raids depuis l'ouest, et les Défias aux masques rouges ont débordé de la Marche de l'Ouest jusque dans les bois. Demandez à n'importe quel fermier d'Elwynn si les soldats du roi viennent quand on les appelle." },
      },
    },
    ["explorers-league"] = {
      title = "La Ligue des explorateurs",
      text = {
        { "Je pouvais difficilement oublier la Ligue. La Ligue des explorateurs est la société d'historiens, d'archéologues et de fouilleurs de Forgefer : ces nains qui aiment mieux lire une ruine que bâtir une salle. Une historienne royale ne saurait rêver meilleure compagnie." },
        { "Ils poursuivent la plus vieille question qui soit : d'où viennent les nains. Leurs fouilles à Uldaman laissent penser que la réponse se trouve du côté des Titans, les façonneurs du monde, et s'il en est ainsi, cela change la manière dont chaque nain devrait se voir. Le roi Magni prend la chose très au sérieux." },
        { "Vous les trouverez dans le Hall des Explorateurs, sous la direction du grand explorateur Magellas. Apportez-leur tout ce qui est ancien, $gvoyageur:voyageuse;, et tout ce qui est étrange. Ils voudront savoir où vous l'avez trouvé, et moi aussi." },
      },
    },
    ["fall-of-lordaeron"] = {
      title = "La chute de Lordaeron",
      text = {
        { "Lordaeron était le premier des royaumes des hommes, et son roi, Terenas Menethil, avait mené l'Alliance pendant la Deuxième Guerre. Quand la peste descendit du nord et que les morts commencèrent à se relever, ce fut son fils, le prince Arthas, paladin de la Main d'argent, qui partit la combattre." },
        { "Arthas la poursuivit trop loin. Il passa au fil de l'épée la cité de Stratholme, frappée par la peste, plutôt que de voir ses habitants se relever, suivit les maîtres de la peste jusqu'au Norfendre, et y prit une lame runique maudite, Deuillegivre. À son retour, le peuple l'acclama jusqu'aux portes. Il entra dans la salle du trône de son père et le tua, et derrière lui le royaume tomba aux mains des morts." },
        { "C'est dans ces ruines que cela s'est passé. Les Réprouvés y marchent chaque jour, et certains d'entre eux étaient dans la foule qui l'acclamait." },
        { side = "Horde", aside = true, sign = "P. F.", "Elle écrit que certains Réprouvés étaient dans la foule qui l'acclamait. Certains d'entre nous y étaient. J'ai plus d'une fois tenté de mettre ce jour par écrit, et je n'y suis pas encore parvenu." },
      },
    },
    ["fandral-staghelm"] = {
      title = "Archidruide Fandral Staghelm",
      text = {
        { "Fandral Staghelm est l'archidruide du Cercle cénarien en l'absence de Malfurion Stormrage, et celui qui mena les druides quand ils firent pousser Teldrassil. Il est vieux, fier et grave, et les druides le suivent avec quelque chose qui ressemble à de la vénération." },
        { "Son peuple se souvient d'un chagrin plus que des autres. Il y a mille ans, pendant la guerre contre l'empire insecte d'Ahn'Qiraj, son fils Valstann partit à cheval sauver le village de Sudevent et ne revint pas. Quelques jours plus tard, le général qiraji Rajaxx s'avança devant l'armée des elfes de la nuit en tenant le jeune elfe dans ses griffes, et le mit en pièces sous les yeux de son père. Quand les dragons et les druides scellèrent enfin les Qiraji derrière le Mur du scarabée, Anachronos remit à Fandral le sceptre qui permettrait de le rouvrir, et Fandral le brisa contre la porte. « Je retrouverai mon fils, dit-il au dragon, dussé-je attendre des millénaires. » Il tient l'Enclave cénarienne de Darnassus, étudie les maux de l'arbre qu'il a planté, et vous dira qu'il les a bien en main." },
      },
    },
    ["forest-trolls"] = {
      title = "Les trolls des forêts",
      text = {
        { "Bien avant qu'il y ait des hommes en Lordaeron, les forêts du nord appartenaient aux trolls de l'empire amani, et ils n'ont jamais pardonné à personne de les leur avoir prises. Quand les hauts-elfes arrivèrent par la mer et s'établirent en Quel'thalas, les Amani leur firent la guerre pendant des générations, jusqu'à ce que les elfes et le premier royaume humain, Arathor, les brisent ensemble pendant les guerres des Trolls. Leur capitale, Zul'Aman, se dresse toujours au cœur des bois de l'est." },
        { "Les trolls revinrent pendant la Deuxième Guerre, quand leur seigneur de guerre Zul'jin mena les tribus des forêts aux côtés de la Horde contre les elfes et les hommes de Lordaeron, et perdirent de nouveau. Il en reste des tribus éparpillées dans les collines : les Witherbark dans les Hautes-terres Arathies et les Hinterlands, les Vilebranch dans leur cité-temple de Jintha'Alor, les Mossflayer dans les bois des Maleterres de l'est, où beaucoup pourrissent désormais de la peste." },
        { "Ils sont grands, à la peau verte et aux défenses saillantes ; ils gardent les anciens dieux des trolls, et certains gardent des coutumes pires encore. Les Revantusk des Hinterlands sont l'exception : ils ont pris le parti de la Horde, et leurs alliés de la Horde se portent garants d'eux." },
      },
    },
    ["frostmane-trolls"] = {
      title = "Les trolls Frostmane",
      text = {
        { "Les Frostmane occupent le pays enneigé à l'ouest de Kharanos, avec des camps jusque dans la vallée des Frigères. Leur repaire abrite des chasseurs de têtes, des voyants et des lanceurs d'ombre, si bien que les montagnards ont plus que des pointes de lance à guetter entre les congères." },
        { "Grelin Whitebeard met en garde contre de nouvelles attaques, et les jeunes nains sont envoyés contre eux presque dès qu'ils quittent la maison. La querelle devient vite familière : un camp troll au-delà du dernier feu ami, un rapport remis aux gardes, et une nouvelle patrouille envoyée dans la même neige." },
      },
    },
    ["furbolgs"] = {
      title = "Les furbolgs",
      text = {
        { "Les furbolgs appartiennent aux forêts du nord de Kalimdor, où leurs villages et leurs totems se dressent depuis des âges près du pays des elfes de la nuit. Ils combattirent la Légion ardente aux côtés des elfes il y a dix mille ans. Leur histoire fait place à de vieilles amitiés, aussi farouchement qu'un étranger soit reçu aujourd'hui dans un de leurs camps." },
        { "Une tribu après l'autre a subi la corruption : les Pin-tordu de Teldrassil, les Noirbois de Sombrivage, les Mort-bois de Gangrebois et les Tombe-hiver du Berceau-de-l'Hiver, entre autres. La folie a fait de voisins des ennemis. En Gangrebois, la terre empoisonnée donne aux elfes de la nuit bien des raisons d'accuser la souillure de la Légion." },
        { client = "classic", "Les Grumegueules ont résisté à ce sort. Ils gardent les tunnels qui relient Gangrebois, Reflet-de-Lune et le Berceau-de-l'Hiver, ainsi qu'un autre repaire fermé en Azshara. Aider contre leurs parents corrompus peut lentement valoir à un voyageur leur confiance." },
        { client = "forever", "Les Grumegueules gardent toujours les tunnels qui relient Gangrebois, Reflet-de-Lune et le Berceau-de-l'Hiver, et l'on peut gagner leur confiance en les aidant contre leurs parents corrompus. Le repaire des Noiregueules, en Azshara, appartient à une tribu distincte, qui a succombé à la corruption." },
      },
    },
    ["gates-of-ironforge"] = {
      title = "Les portes de Khaz Modan",
      text = {
        { "Les passages de la porte Nord et de la porte Sud mènent les voyageurs de Dun Morogh au Loch Modan. Des montagnards tiennent des avant-postes sur les deux routes. En montagne, une route étroite peut exiger autant de gardes qu'une large frontière." },
        { "Le capitaine Rugelfuss expose la difficulté depuis le côté du Loch Modan. Son régiment doit tenir la porte plutôt que de pourchasser les troggs voisins, tandis que la Réserve de Forgefer est engagée sur le front de l'Alliance. Il demande aux aventuriers de défendre les terres que ses soldats ne peuvent couvrir sans quitter leur poste." },
      },
    },
    ["ghost-howl"] = {
      title = "Hurleur fantomatique",
      text = {
        { "Hurleur fantomatique est un grand loup de Mulgore dont la peau porte une terrible blessure, reçue en combattant la Légion ardente. La cicatrice donne au trophée de ce chasseur-là une histoire qui dépasse la poursuite à travers les plaines." },
        { "Skorn Whitecloud reconnaît la peau au village de Sabot-de-Sang. Il offre au chasseur l'une de ses armes et espère que l'esprit du loup a trouvé la paix." },
      },
    },
    ["gnolls"] = {
      title = "Les gnolls",
      text = {
        { "Les Rivepatte pillent Elwynn et la Marche de l'Ouest ; les Poil-moussu occupent les Paluns. Ces meutes ont des histoires différentes. L'avis de recherche de Lardeur prévient qu'il est trop dangereux pour un chasseur seul, tandis que le récit de Rethiel affirme que les Poil-moussu vivaient jadis en paix avec leurs voisins." },
        { "Certaines meutes servent d'autres puissances. Les Sombrepoil des Carmines obéissent à Morganth, et Thule Ravenclaw commande les Poil-Putride morts-vivants des clairières de Tirisfal et de la forêt des Pins argentés. De l'autre côté de la mer, les crin-pâle chassent en Mulgore et les Griffebois vivent en Feralas. Demandez quelle meute vous affrontez, $gvoyageur:voyageuse;. Son nom vous en dira plus sur les ennuis à venir qu'une opinion générale sur les gnolls." },
      },
    },
    ["gnomeregan"] = {
      title = "Gnomeregan",
      text = {
        { "Gnomeregan s'étend sous l'ouest de Dun Morogh : l'ancienne capitale des gnomes, ruinée pendant la crise de la Troisième Guerre. Des troggs envahirent ses salles. Pour les arrêter, les gnomes répandirent des radiations dans leur propre cité." },
        { "Les troggs survécurent. Beaucoup de gnomes moururent, et d'autres furent changés en ces survivants violents qu'on appelle aujourd'hui gnomes lépreux. Ceux qui en réchappèrent trouvèrent refuge à Forgefer. Ce qu'a coûté la tentative se lit encore dans les salles empoisonnées." },
        { "Sicco Thermaplugg y est resté. Le grand bricoleur Mekkatorque le traite de traître et demande aux aventuriers de le tuer. Si vous y entrez, $gvoyageur:voyageuse;, souvenez-vous que c'était une capitale pleine de foyers et d'ateliers. Son peuple essaie encore de sauver ce qu'il en reste." },
      },
    },
    ["gnomeregan-exiles"] = {
      title = "Les Exilés de Gnomeregan",
      text = {
        { "Un peuple sans foyer, et les exilés les plus joyeux que vous rencontrerez jamais. Les gnomes qui ont fui Gnomeregan vivent désormais à Brikabrok, au cœur de Forgefer, et dans des avant-postes comme le dépôt de Steelgrill, en vue de leurs anciennes portes." },
        { "Ne vous laissez pas tromper par leur gaieté. Chaque invention qu'ils essaient, chaque recrue qu'ils forment, prépare un seul jour : celui où ils marcheront sur Gnomeregan pour la reprendre." },
        { "Forgefer leur a offert un abri aussi longtemps qu'il le faudra. La plupart des nains apprécient leur compagnie, sinon leur vacarme." },
      },
    },
    ["goldshire"] = {
      title = "Comté-de-l'Or",
      text = {
        { "Comté-de-l'Or se dresse à un carrefour d'Elwynn, avec l'auberge de la Fierté du lion prête à accueillir les voyageurs et le maréchal Dughan prêt à leur donner du travail. Le village est plus vieux que les guerres. Il a brûlé quand les orcs ont traversé Elwynn pendant la Première Guerre." },
        { "Après la Deuxième Guerre, le peuple de Hurlevent est revenu de son exil en Lordaeron et l'a rebâti. La forge et le marché sont de nouveau animés, et de jeunes aventuriers s'y arrêtent en route pour se faire un nom. Jetez un œil au tableau des primes de Dughan pendant que vous y êtes, $gvoyageur:voyageuse;. Le village s'est remis ; le maréchal a encore bien des soucis." },
      },
    },
    ["great-masquerade"] = {
      title = "La grande mascarade",
      text = {
        { "Le maréchal Reginald Windsor rassembla des preuves contre la conseillère du généralissime Bolvar Fordragon, pour les perdre aussitôt dans les cachots du mont Rochenoire. Une fois secouru, il revint avec de nouvelles preuves et des compagnons prêts à se tenir à ses côtés. Il amena les uns et les autres au donjon de Hurlevent." },
        { "Là, il démasqua dame Katrana Prestor : c'était Onyxia, fille d'Aile de mort et sœur de Nefarian. Elle avait retenu l'armée de Hurlevent chez elle tandis que les orcs de son frère menaçaient les Carmines, et plié Bolvar à sa volonté. Windsor brisa son déguisement devant la cour. Elle s'enfuit vers son repaire, dans le marécage d'Âprefange." },
        { "Windsor mourut dans cet affrontement. Inscrivez son nom, $gvoyageur:voyageuse;, si vous consignez la défaite de la dragonne. Sa part dans l'affaire avait commencé bien avant que quiconque atteigne son repaire." },
      },
    },
    ["green-dragonflight"] = {
      title = "Le Vol draconique vert",
      text = {
        { "Le vol d'Ysera garde le Rêve d'émeraude, et les quatre grands arbres où le Rêve touche le monde éveillé : Seradane dans les Hinterlands, l'Ombrage en Ashenvale, le Bosquet du rêve en Feralas et le Bosquet du crépuscule au Bois de la Pénombre. Les druides parcourent le Rêve grâce au pacte que leurs ancêtres ont conclu avec Ysera ; les dragons, eux, parcourent rarement le monde." },
        { "Tous ne se portent pas bien. Quelque chose s'est glissé dans le Rêve et a perverti certains des propres enfants d'Ysera ; les quatre qui hantent désormais les grands arbres ont leur propre page. Avant eux, il y eut Eranikus, endormi au-dessus du temple englouti du marais des Chagrins et pris dans le même cauchemar." },
        { "Itharius, un autre membre du vol, attend dans une grotte de ce marais et cherche des mortels capables d'aider à racheter Eranikus. Tandis que les gardiens corrompus hantent toujours les grands arbres, l'un des leurs demande à des inconnus de ramener un dragon chez lui." },
      },
    },
    ["grimtotem"] = {
      title = "Le Totem sinistre",
      text = {
        { "La plupart des taurens vivent selon la paix de la Terre-Mère. Pas ceux du Totem sinistre. C'est une tribu qui estime que les autres races n'ont aucun droit sur Kalimdor, taurens en désaccord compris, et qui se bat pour le reprendre sans règles ni pitié." },
        { "Leur matriarche, Magatha Grimtotem, l'Ancienne Mégère, vit à Thunder Bluff même et siège parmi les anciens, ce qui en dit long sur la patience de Cairne Bloodhoof. Ses guerriers sont moins polis. Ils lancent des raids dans les Serres-Rocheuses, tiennent la cime de Noir-nuage à Mille pointes, harcèlent le poste de Librevent, et gardent une enceinte en Feralas. Demandez à un tauren de Librevent ce qu'il pense du Totem sinistre, puis reculez d'un pas." },
      },
    },
    ["hall-of-thanes"] = {
      title = "La salle des Thanes",
      text = {
        { "Sous Forgefer s'étendent les cavernes du Vieux Forgefer, et parmi elles un lieu que les nains appellent la salle des Thanes. Les Sombrefer en ont trouvé le chemin. Une carte prise à leurs espions à la base d'Ironband montre des tunnels et d'anciennes routes qui convergent sous la cité, et le terre-voyant Farsen, venu du Nid-de-l'Aigle, les a suivis jusqu'à la salle et jusqu'au Sombrefer qui y commande, un certain Durgen Dirgehammer." },
        { "Les morts de la salle ne sont pas en paix. Afadra Mur-de-Dun, gardienne du savoir de Forgefer, demande aux voyageurs d'apaiser les esprits de Courbenclume, et l'un d'eux, Faldrim Courbenclume, semble avoir gardé une vieille rancune bien au-delà de la tombe. Le roi Magni veut la tête du commandant. J'aimerais que la Ligue examine les lieux comme il se doit, une fois les Sombrefer partis." },
      },
    },
    ["hamuul-runetotem"] = {
      title = "Archidruide Hamuul Runetotem",
      text = {
        { "L'archidruide Hamuul Runetotem se tient sur la cime des Anciens de Thunder Bluff, parmi les maîtres et les guides spirituels des taurens. Sa place là-haut donne aux druides une voix dans la cité autant qu'un foyer." },
        { "Les rapports venus des cavernes des Lamentations lui amènent des aventuriers d'au-delà de Mulgore. Il les envoie à Nara Wildmane pour poursuivre l'enquête." },
      },
    },
    ["harpies"] = {
      title = "Les harpies",
      text = {
        { "Les harpies nichent dans tout Kalimdor, chassant et lançant des sorts, avec des ailes et des serres pour les porter au-dessus du sol. Les Terrevent occupent Durotar, les Furie-des-vents Mulgore, les Ensorçaile les Tarides et les Rougefurie les Serres-Rocheuses. Leurs nuées se sont fait des ennemis parmi les établissements d'en bas." },
        { "Ruul Eagletalon envoie des chasseurs contre les Furie-des-vents en guise d'épreuve. Les druides des Serres-Rocheuses veulent reprendre le Val calciné aux Rougefurie pour le restaurer. Un voyageur qui passe sous leurs aires a une raison toute pratique d'apprendre quelle nuée les tient." },
      },
    },
    ["high-elves"] = {
      title = "Les hauts-elfes",
      text = {
        { "Les hauts-elfes furent d'abord des elfes de la nuit : des Bien-nés de la cour d'Azshara qui survécurent à la Fracture sans pouvoir renoncer à leur magie. Quand les druides l'interdirent sous peine de mort, leur chef, Dath'Remar, répondit par une tempête de sorts sur Ashenvale. Les druides ne voulurent pas tuer tant des leurs. Ils les exilèrent plutôt, et le peuple de Dath'Remar fit voile vers l'est à travers le Maelström, ravi d'être débarrassé de ses prudents cousins." },
        { "Ils touchèrent terre dans le nord de ce que les hommes appelleraient Lordaeron et s'établirent d'abord dans les clairières de Tirisfal, jusqu'à ce que, au bout de quelques années, beaucoup d'entre eux commencent à perdre la raison ; la rumeur disait que quelque chose de maléfique dormait sous cette terre, et cela ne fut jamais prouvé. Coupés du Puits, ils perdirent leur immortalité en chemin, devinrent plus petits et plus pâles, et disputèrent chaque lieue aux trolls amani. Enfin, ils fondèrent Quel'thalas au cœur des forêts du nord, sur une terre que les trolls tenaient pour sacrée, et l'entourèrent de pierres runiques. Dath'Remar prit le nom de Sunstrider, « celui qui marche dans le jour », et son peuple est depuis lors enfant du soleil." },
        { "Quel'thalas n'est plus. Les elfes qu'un voyageur rencontre sont ce qu'il en reste : des forestiers qui tiennent le gîte de Quel'Lithien au bord des Maleterres, les elfes du Haut-val au gîte de Quel'Danil dans les Hinterlands, des errants çà et là. Ils restent fiers, même en exil. Vu tout ce qu'ils ont perdu, j'ai du mal à le leur reprocher." },
      },
    },
    ["high-tinker-mekkatorque"] = {
      title = "Grand Bricoleur Mekkatorque",
      text = {
        { "Gelbin Mekkatorque dirige les gnomes depuis Brikabrok, à Forgefer. Les nains ont donné un refuge à son peuple, mais leur propre capitale reste sous Dun Morogh. Un foyer emprunté à des amis ne saurait effacer la perte de Gnomeregan." },
        { "Les radiations répandues contre les troggs qui l'envahissaient n'ont pas su les exterminer et ont dévasté les gnomes eux-mêmes. Mekkatorque faisait jadis confiance à Sicco Thermaplugg ; il l'accuse aujourd'hui d'avoir trahi la cité et demande aux aventuriers d'y entrer pour le tuer." },
      },
    },
    ["highborne"] = {
      title = "Les Bien-nés",
      text = {
        { "Les Bien-nés étaient la caste supérieure des elfes de la nuit, les serviteurs choisis de la reine Azshara, qui étudièrent le Puits d'éternité jusqu'à apprendre la magie, puis l'aimèrent plus que tout. Ce fut leur art des sorts qui attira Sargeras sur le monde, et leur reine et sa cour qui ouvrirent la voie à sa Légion." },
        { "Tous ne partagèrent pas son sort. Certains survécurent à la Fracture parmi les autres elfes de la nuit et, exilés pour s'être accrochés à leur magie, devinrent les hauts-elfes ; d'autres tinrent bon à Eldre'Thalas, où les Shen'dralar gardent encore leurs propres secrets. Beaucoup moururent tout simplement, et ne trouvèrent pas le repos." },
        { "Leurs morts sont faciles à trouver : ils gémissent dans les ruines de Sombrivage, errent dans Azshara sous forme d'apparitions et de jeunes liches, souffrent au bord du lac gelé de Kel'Theril, au Berceau-de-l'Hiver. Dix mille ans, c'est long pour regretter, $gvoyageur:voyageuse;. L'un d'eux au moins, au bord du lac, semble le regretter sincèrement." },
      },
    },
    ["hogger"] = {
      title = "Lardeur",
      text = {
        { "L'avis de recherche de la garnison du ruisseau de l'ouest décrit Lardeur comme un énorme gnoll, campé plus au sud, dans le sud-ouest d'Elwynn. Il appartient aux Rivepatte, et les gardes de Hurlevent n'ont pas réussi à le capturer. Une récompense est offerte pour sa griffe." },
        { "L'avis conseille de venir en groupe. Suivez ce conseil, $gvoyageur:voyageuse;. Un garde qui admet avoir besoin d'aide est plus utile qu'un aventurier persuadé de ne pas en avoir besoin." },
      },
    },
    ["humans"] = {
      title = "Les humains",
      text = {
        { "Le premier royaume de l'humanité fut Arathor, élevé à Strom dans les hautes terres qui portent encore son nom. Son roi, Thoradin, rassembla les tribus éparses contre les trolls amani, et pendant cette guerre les hauts-elfes de Quel'thalas apprirent à cent humains à manier la magie. D'Arathor naquirent, avec le temps, sept royaumes : Hurlevent, Lordaeron, Gilnéas, Alterac, Stromgarde, Kul Tiras et la cité des mages, Dalaran." },
        { "Les orcs franchirent la Porte des Ténèbres et brûlèrent Hurlevent en premier. Son peuple s'enfuit au nord, et l'Alliance qui gagna la Deuxième Guerre fut bâtie en Lordaeron. Puis la peste et le Fléau prirent Lordaeron elle-même, Gilnéas s'enferma derrière son mur, et Dalaran tomba. Hurlevent, rebâtie en pierre blanche, est la plus grande cité humaine qui reste, et un enfant-roi y siège sur le trône sous la garde d'un régent, tandis que son père a disparu." },
        { "C'est un peuple à la vie brève et à la tête dure, $gvoyageur:voyageuse;. Ils se querellent entre eux plus qu'il n'est bon pour eux, et rebâtissent plus vite que quiconque de ma connaissance. La Ligue a appris à prendre leurs cartes au sérieux, et leurs promesses de paiement avec un peu de prudence." },
      },
    },
    ["hunters"] = {
      title = "Chasseurs",
      text = {
        { "Chaque peuple qui vit près du monde sauvage a ses chasseurs. Les nains ont leurs montagnards, à la visée sûre sur n'importe quelle pente ; les elfes de la nuit, leurs chasseresses et leurs Sentinelles ; les orcs et les trolls, leurs pisteurs et leurs dompteurs de bêtes ; les taurens, des braves qui suivent encore les troupeaux comme le faisaient leurs grands-parents." },
        { "Ce qui distingue un chasseur, c'est son compagnon. Un loup, un félin, un ours, un raptor, une chouette : apprivoisé dans la nature, il apprend à combattre aux côtés du chasseur. Le nourrir et le soigner font autant partie de la vocation qu'apprendre à tirer. Encore faut-il convaincre la bête que ce nouvel arrangement en vaut la peine." },
        { client = "forever", "Les humains se forment désormais eux aussi à la chasse, et les éolides amènent des chasseurs à l'Alliance comme à la Horde." },
        { "La Ligue emploie des chasseurs comme guides depuis qu'elle existe, $gvoyageur:voyageuse;. Ils trouvent la route et le dîner, et s'assurent que ni l'un ni l'autre ne trouve les fouilleurs le premier." },
      },
    },
    ["ironforge"] = {
      title = "Forgefer",
      text = {
        { "Forgefer n'est pas bâtie sur la montagne : elle est bâtie dedans. Ses salles sont creusées au cœur de la montagne, et en son centre brûle la Grande forge." },
        { "La cité tourne autour de la forge comme une roue. Le roi Magni tient sa cour au Haut-Siège, la Garde militaire forme les défenseurs de la montagne, les mages se tiennent à la Garde mystique, et depuis la chute de Gnomeregan les gnomes exilés ont fait de Brikabrok leur domaine : bruyant, ingénieux et nostalgique. Sous tout cela court le Tram des profondeurs, œuvre gnome, qui emmène les voyageurs sous les montagnes jusqu'à Hurlevent." },
        { client = "forever", "Sous le Vieux Forgefer s'étend la salle des Thanes. Des intrus sombrefer y ont fait une brèche, et Magni veut la tête de leur commandant, Durgen Dirgehammer. Même ici, les plus vieilles salles d'une cité peuvent devenir ses plus récents soucis." },
        { "Et puis il y a le Hall des Explorateurs, où la Ligue garde sa bibliothèque et ses trouvailles : des reliques d'Uldaman, les ossements de bêtes que personne n'a vues vivantes, et des cartes de lieux que la plupart des nains ne connaîtront jamais que par les livres. Quant à moi, vous me trouverez au Haut-Siège, à quelques pas du trône du roi. Venez me voir. Je manque toujours de gens qui sont vraiment allés quelque part." },
        { side = "Horde", aside = true, sign = "P. F.", "Son invitation part d'un bon sentiment. Je ne conseillerais pas de l'accepter aux couleurs de la Horde." },
      },
    },
    ["katrana-prestor"] = {
      title = "Dame Katrana Prestor",
      text = {
        { "Dame Katrana Prestor est la plus proche conseillère du généralissime, et fort admirée à la cour : savante, gracieuse et très belle. Elle en sait long sur bien des sujets, les dragons parmi eux, et Bolvar Fordragon lui fait entièrement confiance." },
        { "Tout le monde ne la lui fait pas. Quand le magistrat Solomon de Comté-du-Lac supplia le trône d'envoyer des soldats contre les orcs Blackrock, ce fut le conseil de dame Prestor qui les retint chez eux, et il est au moins un maréchal de Hurlevent qui ne le lui a jamais pardonné. Je ne consigne que ce que l'on sait. Une érudite qui en écrit davantage sur une dame de la cour a intérêt à être très sûre d'elle." },
      },
    },
    ["kharanos"] = {
      title = "Kharanos",
      text = {
        { "Kharanos se trouve dans le cœur glacé de Dun Morogh, sur la route entre les terrains d'entraînement de la vallée des Frigères et les portes de Forgefer. C'est une petite ville, à l'aune des nains : une forge, quelques solides maisons, et le bâtiment qui fait sa renommée, la distillerie Thunderbrew, où la famille Thunderbrew perfectionne ses bières depuis plus longtemps que quiconque ne veut l'admettre." },
        { "Ne prenez pas la chaleur du foyer pour de la sécurité. Les trolls Frostmane tiennent les collines de l'ouest, les troggs ne cessent de remonter des profondeurs, et depuis la chute de Gnomeregan ses exilés partagent ces routes avec nous. La ville garde pourtant ses portes ouvertes : un nain qui ferme sa porte à un voyageur transi n'en est pas un." },
      },
    },
    ["kobolds"] = {
      title = "Les kobolds",
      text = {
        { "Chaque mineur de l'Alliance a une histoire de kobold, et la plupart se terminent par une pioche perdue. Les kobolds sont de petites créatures des tunnels à tête de rat, lâches quand ils sont seuls et dangereux en nombre, et ils sont toujours en nombre. Ils portent des bougies sur la tête pour éclairer le noir, et se battront à mort pour une bougie bien après avoir fui devant une épée." },
        { "On en trouve partout où il y a à creuser. Un clan venu des Carmines a envahi les mines de la forêt d'Elwynn et de la Marche de l'Ouest, les Rats des tunnels se sont terrés au-dessus de Thelsamar, les Sèche-moustache servent les géants des Hautes-terres Arathies, et les Mufle-de-gravier fouillent le minerai à Mille pointes." },
        { "Il est facile d'en rire. Les fermiers d'Elwynn, qui leur perdent leur bétail et leurs récoltes, n'en rient pas." },
      },
    },
    ["leper-gnomes"] = {
      title = "Les gnomes lépreux",
      text = {
        { "Tous les gnomes n'ont pas fui Gnomeregan. Certains ont survécu aux radiations et en ont été changés, le corps ravagé et l'esprit devenu étrange et violent. Les nains les appellent gnomes lépreux, et les exilés n'aiment pas du tout parler d'eux." },
        { "Ils hantent les abords de l'ancienne cité et les dépôts alentour, récupérant ce qu'ils peuvent et attaquant quiconque s'approche trop." },
        { "Si vous devez les combattre, $gvoyageur:voyageuse;, souvenez-vous qu'ils furent un jour les voisins de quelqu'un." },
      },
    },
    ["mages"] = {
      title = "Mages",
      text = {
        { "L'art humain de la magie commença avec cent élèves. Pendant les guerres des Trolls, les hauts-elfes de Quel'thalas leur apprirent à lancer des sorts en échange d'une aide contre les Amani, et leurs héritiers fondèrent Dalaran et son conseil dirigeant, le Kirin Tor. La cité devint le grand foyer du savoir arcanique des humains." },
        { "Dalaran tomba pendant la Troisième Guerre, et ses élèves se dispersèrent : à Theramore avec Jaina Proudmoore, à Hurlevent, à Fossoyeuse parmi les Réprouvés, dont certains y avaient étudié dans leur première vie. Les gnomes et les trolls Darkspear ont leurs propres mages. Une éducation au Kirin Tor est une des voies vers cet art, même si ses diplômés en parlent parfois comme si c'était la seule." },
        { client = "forever", "On a vu aussi des orcs s'adonner au métier de mage, et l'Ordre suprême des éolides est descendu chercher le savoir arcanique que leur peuple avait perdu." },
        { "Un mage fait naître le feu, le givre et la pure force des arcanes, ainsi qu'une bonne quantité d'eau fraîche. J'en recommande un sur chaque chantier de fouilles, $gvoyageur:voyageuse;, ne serait-ce que pour l'eau." },
      },
    },
    ["magni-bronzebeard"] = {
      title = "Roi Magni Bronzebeard",
      text = {
        { "Le roi Magni Bronzebeard tient sa cour au Haut-Siège de Forgefer et règne sur la cité qui appartient à son clan depuis la guerre des Trois Marteaux. Il est l'aîné de trois frères. Muradin est parti vers le nord avec le prince de Lordaeron pendant la Troisième Guerre, et l'on est sans nouvelles de lui depuis. Brann est l'explorateur le plus célèbre de la Ligue, et l'un des plus difficiles à suivre à la trace." },
        { "Magni suit de près les travaux de la Ligue. Les trouvailles d'Uldaman laissent penser que les nains furent façonnés il y a bien longtemps par les Titans. Un roi d'une si longue lignée a de bonnes raisons de demander où elle commence, et une historienne qui se tient à quelques pas de son trône a toutes les raisons de saluer son intérêt." },
        { "Sa fille lui cause un souci plus pressant. La princesse Moira se trouve dans la cité sombrefer sous le mont Rochenoire, mariée à l'empereur Dagran Thaurissan. Forgefer parle d'enlèvement, et Magni promet une récompense digne d'un héros à qui la ramènera. Si vous acceptez cette charge, $gvoyageur:voyageuse;, vous portez les espoirs d'un père autant que les ordres d'un roi." },
      },
    },
    ["mekgineer-thermaplugg"] = {
      title = "Mekgénieur Thermaplugg",
      text = {
        { "Sicco Thermaplugg est resté à Gnomeregan tandis que le grand bricoleur Mekkatorque mène ses exilés depuis Forgefer. Le grand bricoleur lui faisait jadis confiance. Cette confiance a fini en accusation de trahison, et en appel à sa mort." },
        { "Les radiations répandues dans la cité n'ont pas su exterminer les troggs et ont dévasté ses habitants gnomes. Thermaplugg règne dans les ruines, parmi les créatures que la tentative devait détruire et les survivants qu'elle a laissés derrière elle." },
        { "Mekkatorque demande aux aventuriers de porter son jugement dans ces salles." },
      },
    },
    ["mulgore"] = {
      title = "Mulgore",
      text = {
        { "Après la poussière rouge de Durotar et l'herbe jaune des Tarides, Mulgore est une surprise : des plaines vertes et vallonnées, des lacs et des ruisseaux limpides, des troupeaux de kodos et de trotteurs des plaines, et de grandes mesas au sommet plat qui se dressent au-dessus de l'herbe. C'est la patrie des taurens, et ils la tiennent, pour la première fois de leur longue histoire, comme la leur." },
        { "Pendant des générations, les taurens errèrent dans les plaines de Kalimdor, harcelés par les centaures partout où ils allaient. Quand les orcs arrivèrent en Kalimdor, Thrall aida le peuple de Cairne Bloodhoof à repousser les centaures et à prendre ces prairies, et les tribus s'y rassemblent depuis. Pourtant, Mulgore n'est pas sans soucis : les hurans Dos-hirsute lancent des raids depuis les ravins, les gnolls crin-pâle chassent ses bêtes, et les gobelins de la KapitalRisk ont creusé une mine dans ses falaises et souillé ses puits malgré le refus exprès des taurens." },
      },
    },
    ["murlocs"] = {
      title = "Les murlocs",
      text = {
        { "Huttes et filets de pêche murlocs bordent les rivages des deux continents, des eaux d'Elwynn à Sombrivage. Chasseurs et oracles peuplent leurs villages, attaquant souvent ceux qui approchent. Un voyageur peut croiser plusieurs tribus sans apprendre grand-chose de l'histoire de leur présence." },
        { "Une tribu a joué un rôle décisif dans le voyage de la nouvelle Horde. Des murlocs au service d'une sorcière des mers capturèrent des trolls et des orcs sur les îles des Darkspear. Les fidèles de Thrall se frayèrent un chemin vers la liberté ; Sen'jin mourut, et les Darkspear survivants firent voile avec eux vers Kalimdor. Cette alliance commença au bord d'un rivage défendu par des murlocs, bien avant d'avoir un foyer en Durotar." },
      },
    },
    ["naga"] = {
      title = "Les nagas",
      text = {
        { "La Fracture emporta sous la mer les Bien-nés d'Azshara avec leur capitale. Ils survécurent, changés en êtres couverts d'écailles, au bas du corps de serpent, avec des nageoires et parfois quatre bras. Ils bâtirent un royaume sous les eaux. Les vieux récits y placent toujours leur reine." },
        { "Ils remontèrent à la surface pendant la Troisième Guerre, quand dame Vashj mena des nagas au service d'Illidan. Leurs bandes tiennent désormais la grève de Zoram et le temple englouti de Brassenoire, les côtes en ruine d'Azshara et de Sombrivage, et des rivages en Feralas, en Désolace et dans le marécage d'Âprefange." },
        { "L'histoire des Bien-nés ne s'est pas arrêtée quand leurs cités ont sombré, $gvoyageur:voyageuse;. Ces mêmes Bien-nés se disputent aujourd'hui des places le long des côtes du continent, aussi changés que la terre qu'ils ont connue." },
      },
    },
    ["night-elves"] = {
      title = "Les elfes de la nuit",
      text = {
        { "Les kaldorei sont le plus ancien peuple que la Ligue ait rencontré, et ils sont trop polis pour nous le rappeler souvent. Il y a dix mille ans, leurs Bien-nés puisèrent dans le Puits d'éternité jusqu'à ce que la Légion ardente vienne le prendre, et la guerre qui suivit brisa le monde. Ensuite, les survivants renoncèrent aux arcanes. Ils se tournèrent vers les druides de Malfurion Stormrage et les prêtresses d'Elune, et plantèrent sur le mont Hyjal un Arbre-Monde qui les empêcha de vieillir." },
        { "Pendant la Troisième Guerre, la Légion revint à Hyjal. Pour détruire le démon Archimonde, les elfes de la nuit sacrifièrent l'Arbre, et leur immortalité avec lui. Fandral Staghelm a depuis fait pousser Teldrassil au large de Sombrivage, et Darnassus se dresse dans ses branches ; quant à savoir si le nouvel Arbre est béni comme l'était l'ancien, les druides ne le disent pas à voix haute." },
        { "Ils vieillissent désormais, et ils apprennent ce que cela signifie, $gvoyageur:voyageuse;. Tyrande Whisperwind les guide depuis le temple de la Lune, tandis que Malfurion est perdu dans le Rêve. Si un elfe de la nuit semble peser chaque mot, souvenez-vous qu'il y a quelques années encore, ils avaient tout le temps du monde pour les choisir." },
      },
    },
    ["noble-conspiracy"] = {
      title = "La conspiration des nobles",
      text = {
        { "Une lettre trouvée sur le corps d'Edwin VanCleef ramena l'enquête sur les Défias à l'intérieur même de Hurlevent. Elle mena à Bazil Thredd, à la Prison, à un visiteur se servant d'un faux nom, et enfin à l'assassin appelé Marzon Lame silencieuse." },
        { "Marzon travaillait pour le seigneur Gregor Lescovar, qui livrait les secrets de la cour à la Confrérie. Les relations du noble rendaient difficile un procès public. Les alliés du SI:7 arrangèrent une rencontre dans les jardins du château, où Lescovar et Marzon furent tués." },
        { "Le grief des maçons avait commencé quand des nobles refusèrent de payer la reconstruction de Hurlevent. Lescovar aidait désormais la rébellion que ce refus avait contribué à faire naître. L'emprise de VanCleef sur la cité allait bien au-delà des gens qui portaient des masques rouges." },
      },
    },
    ["northshire-abbey"] = {
      title = "Abbaye de Comté-du-Nord",
      text = {
        { "L'abbaye de Comté-du-Nord se dresse dans une vallée à la lisière nord d'Elwynn. Ses clercs servirent Hurlevent pendant la Première Guerre, avant que le royaume ne tombe aux mains de la Horde. Après la Deuxième Guerre, Alonsus Faol aida à rebâtir la cité et à refonder la Confrérie de Comté-du-Nord." },
        { "L'abbaye instruit désormais les recrues du royaume aux armes comme à la foi. Les deux ont leur utilité tout près : des kobolds occupent la mine, des loups rôdent dans la vallée, et des voleurs défias ont pris les vignes." },
      },
    },
    ["ogres"] = {
      title = "Les ogres",
      text = {
        { "Les ogres sont venus dans ce monde avec la Horde, de la même terre rouge que les orcs, et ont combattu pendant la Deuxième Guerre comme ses poings les plus lourds. Le démoniste Gul'dan les améliora, à sa façon : il se servit de l'Autel des tempêtes pour donner à des ogres les pouvoirs des ogres-mages, et les leurs règnent encore sur bien des clans." },
        { "Après la défaite de la Horde, des clans d'ogres s'installèrent dans les contrées sauvages, et y sont restés : les Mo'grosh au Loch Modan, les Brisepoing au Bois de la Pénombre, les Cassecrête en Alterac, les Rochepoing dans les Hautes-terres Arathies, les Crache-poussières dans les Terres ingrates, les Mosh'Ogg dans la vallée de Strangleronce et les Cognepeur à la Porte des Ténèbres ; de l'autre côté de la mer, les Gordunni en Feralas et les Cognedune en Tanaris. Les Gordok se sont installés comme chez eux dans les ruines d'une cité elfique de Feralas, et couronnent quiconque tue leur roi." },
        { "Tous les clans n'ont pas oublié la vieille alliance. Les Cognepierre du marécage d'Âprefange combattent aux côtés de la Horde à Mur-de-Fougères, et les orcs disent du bien d'eux. Les autres préféreraient vous manger que de vous parler." },
      },
    },
    ["orcs"] = {
      title = "Les orcs",
      text = {
        { "Les orcs sont venus de Draenor, un monde de clans et de chamans, et ils ne sont pas venus de leur plein gré. Le démoniste Gul'dan et son Conseil des ombres, au service du démon Kil'jaeden, leur enseignèrent la magie gangrenée et menèrent leurs chefs à boire le sang de Mannoroth. La Horde qui franchit la Porte des Ténèbres naquit de ce marché, et elle brûla Hurlevent avant que l'Alliance ne la brise pendant la Deuxième Guerre." },
        { "Les orcs vaincus furent parqués dans des camps d'internement, apathiques à mesure que la fureur des démons les quittait. Thrall, élevé en esclave à Fort-de-Durn, les libéra, leur rendit les anciennes voies du chaman et les mena par-delà la mer jusqu'à Kalimdor. Au mont Hyjal, ils combattirent la Légion aux côtés des humains et des elfes de la nuit, et quand Grom Hellscream tua Mannoroth, la malédiction du sang fut brisée." },
        { "Ils nommèrent leur nouvelle terre Durotar, d'après le père de Thrall, et bâtirent Orgrimmar dans ses rochers. C'est un peuple fier, qui garde un long souvenir d'avoir été utilisé, $gvoyageur:voyageuse;. Offrez à un orc du respect et de la franchise, et ne lui demandez jamais de servir à nouveau un maître." },
      },
    },
    ["orgrimmar"] = {
      title = "Orgrimmar",
      text = {
        { "Orgrimmar est la capitale de la Horde, bâtie dans un grand canyon au nord de Durotar et nommée d'après Orgrim Doomhammer, le chef de guerre qui mena la Horde pendant la Deuxième Guerre et mourut en combattant pour la libérer des camps. Thrall porte toujours son marteau. Les gobelins ont aidé à la bâtir, et cela se voit : ce n'est que bois, pointes et peaux sur la pierre, chaud comme une forge et bruyant comme un camp de guerre." },
        { "En son cœur se dresse le fort Grommash, nommé d'après Grom Hellscream, qui but le sang du démon Mannoroth et condamna son peuple, puis tua Mannoroth de sa propre hache et le libéra. Dans la vallée des Esprits, les chamans et les trolls entretiennent leurs feux, et dans la faille de l'Ombre, m'a-t-on dit, il y a des démonistes que la Horde tolère plus qu'elle ne leur fait confiance." },
        { "Ce n'est pas une cité qui accueille les nains. Mais c'est une vraie cité, et les orcs l'ont bâtie en une poignée d'années à partir de rien, ce qu'on ne peut pas dire de la plupart." },
      },
    },
    ["paladins"] = {
      title = "Paladins",
      text = {
        { "Les premiers paladins furent les chevaliers de la Main d'argent, fondés pendant la Deuxième Guerre par l'archevêque Alonsus Faol pour porter la Lumière sacrée sur le champ de bataille. Uther le Porteur de lumière les mena, et ils combattirent pour l'Alliance pendant la guerre et la longue paix qui suivit." },
        { "La Troisième Guerre brisa l'ordre. Le prince Arthas, lui-même paladin, se retourna contre tout ce qu'il défendait, et Uther tomba sous ses coups à Andorhal. Les chevaliers survivants se dispersèrent à Hurlevent, à Forgefer et dans les Maleterres, où certains servent l'Aube d'argent, et d'autres l'idée plus dure que la Croisade écarlate se fait de la Lumière. Le même serment a mené ceux qui le prêtent vers des compagnies amèrement différentes." },
        { client = "classic", "Aujourd'hui, seule l'Alliance forme des paladins : des humains et des nains qui jurent fidélité à la Lumière dans la cathédrale de la Lumière ou à la Garde mystique de Forgefer." },
        { client = "forever", "Humains et nains jurent toujours fidélité à la Lumière à Hurlevent et à Forgefer, tandis que certains Réprouvés embrassent désormais eux aussi la vocation de paladin. La mort ne leur a pas fermé la Lumière." },
      },
    },
    ["parqual-fintallas"] = {
      title = "Parqual Fintallas",
      text = {
        { "Avant la peste, Parqual Fintallas était l'un des grands historiens de Lordaeron. Il est aujourd'hui un Réprouvé et se tient à l'Apothicarium de Fossoyeuse, toujours à l'étude, même si l'objet de ses études a changé avec lui." },
        { "Il soumet les jeunes héros de la Horde à une épreuve de savoir. Avant de poser sa question, il les envoie au Monastère écarlate chercher la « Naissance de la menace des morts-vivants », un livre dont la Croisade se sert pour former ses paladins contre ceux de son espèce, et il attend d'eux qu'ils l'aient lu. Le savoir, soutient-il, compte plus que la force. Je n'ai jamais entendu un historien soutenir le contraire." },
        { "Nous ne nous sommes jamais rencontrés, et il est peu probable que cela arrive. On me dit pourtant qu'un exemplaire de ce registre lui est parvenu, par des chemins que je préfère ignorer. J'espère qu'il le trouve juste. Il saurait mieux que la plupart où il ne l'est pas." },
        { side = "Horde", aside = true, sign = "P. F.", "Elle est plus aimable envers moi que les livres de la Croisade." },
      },
    },
    ["priests"] = {
      title = "Prêtres",
      text = {
        { "Les prêtres servent la foi de leur peuple, et la foi des peuples diffère. À Hurlevent et à Forgefer, ils servent la Lumière sacrée. Les prêtresses des elfes de la nuit servent Elune, la lune, et gardent ses temples depuis dix mille ans." },
        { "Du côté de la Horde, les Darkspear ont leurs propres prêtres, et les Réprouvés gardent aussi les leurs, dont les prières penchent vers l'ombre aussi volontiers que vers la Lumière. Un prêtre, quel que soit son peuple, sait panser une blessure, protéger un ami, relever les morts, ou retourner ce même pouvoir contre un ennemi." },
        { client = "forever", "Les gnomes comptent désormais des prêtres parmi les leurs, une vocation de plus dans la compagnie de Brikabrok." },
        { "C'est la compagnie la plus bienvenue sur un chantier de fouilles, $gvoyageur:voyageuse;, et la moins appréciée jusqu'à ce que quelqu'un tombe dans un puits." },
      },
    },
    ["quilboar"] = {
      title = "Les hurans",
      text = {
        { "Pendant la guerre des Anciens, un grand demi-dieu sanglier, Agamaggan, combattit la Légion ardente et tomba. Là où son sang imprégna le sol des Tarides poussèrent des épines colossales, et les hurans vinrent vivre parmi elles : un peuple d'hommes-sangliers, hérissés de piquants et armés de défenses, qui tiennent les épines pour sacrées et se disent ses enfants. Le plus grand de ces dédales d'épines, ils l'appellent Tranchebauge." },
        { "Les tribus se répandirent dans les Tarides, en Mulgore et en Durotar : les Tranchecrin, les Dos-hirsute, ceux de Tranchebauge dans leur kraal. Ils combattent les centaures, les taurens et les orcs avec une même fureur, et les combattaient bien avant l'arrivée de la Horde. Il y a désormais pire. Dans les Souilles de Tranchebauge, la tribu de la Tête de Mort a passé un marché avec le Fléau, et une liche du nom d'Amnennar le Porte-froid siège au cœur des épines d'Agamaggan." },
      },
    },
    ["ragefire-chasm"] = {
      title = "Le gouffre de Ragefeu",
      text = {
        { "Sous Orgrimmar s'étendent des cavernes de feu et de roche en fusion, et la Horde a bâti sa capitale par-dessus sans, semble-t-il, regarder de très près. Des troggs en sont d'abord remontés. Puis la Lame brûlante : un culte de la Lame ardente qui s'est installé dans les profondeurs, sous les pieds mêmes du chef de guerre, avec parmi eux un démon appelé Taragaman l'Affameur." },
        { "Le peuple de Thrall a envoyé les jeunes de la Horde nettoyer les lieux. Je vois peu de meilleures leçons sur ce sur quoi une capitale est bâtie." },
      },
    },
    ["razor-hill"] = {
      title = "Tranchecolline",
      text = {
        { "Tranchecolline est une ville de garnison sur la route de la vallée des Épreuves à Orgrimmar : une caserne, une auberge, une tour de guet et une palissade de bois taillé en pointe sur une colline au-dessus de la mer. Son commandant, Gar'Thok, la tient pour le chef de guerre et passe le plus clair de ses journées à repousser tout ce qui remonte des canyons ou arrive de la côte." },
        { "Juste au sud se trouve le donjon de Tiragarde, où les hommes de Kul Tiras s'accrochent encore au rivage de Durotar, et l'épave de la flotte de leur amiral pourrit au large de la plage. Les grunts de Tranchecolline gardent un œil attentif sur les deux." },
      },
    },
    ["red-rocks"] = {
      title = "Les Rochers rouges",
      text = {
        { "À l'est de Thunder Bluff, parmi de grandes pierres rouges, se trouve le cimetière sacré des taurens. Seuls les plus valeureux reposent aux Rochers rouges : les guerriers qui aidèrent à fonder et à défendre Thunder Bluff, et ceux qui donnèrent leur vie pour leur tribu et leurs chefs. On dit que les esprits des ancêtres y marchent encore." },
        { "Les jeunes y viennent pour le dernier des rites, le rite de la Sagesse, recevoir la bénédiction de ces ancêtres. Ces derniers temps, les hurans creusent dans les tombes, et le vieux gardien du savoir qui veille sur elles n'a plus la force de les chasser. Si vous voulez vous faire un ami de chaque tauren de Mulgore, il n'y a pas de moyen plus rapide." },
      },
    },
    ["regency-of-stormwind"] = {
      title = "La régence de Hurlevent",
      text = {
        { "Le roi Varian Wrynn a disparu. C'était le fils du roi Llane, assassiné pendant la Première Guerre, et il a grandi parmi les réfugiés de Hurlevent, en Lordaeron. Son sort reste inconnu dans la cité même sur laquelle il régnait." },
        { "Son jeune fils Anduin porte la couronne. Le généralissime Bolvar Fordragon tient le royaume pour lui, commande ses forces et veille sur l'enfant. La conseillère royale, dame Katrana Prestor, se tient aux côtés de Bolvar." },
        { "L'armée de Hurlevent est dispersée, et les demandes arrivent de toutes parts." },
      },
    },
    ["rockjaw-troggs"] = {
      title = "Les troggs",
      text = {
        { "Les annales des Titans, à Uldaman, décrivent les troggs comme un résultat raté de la création des terrestres. Ils furent scellés sous terre jusqu'à ce que des fouilles naines ouvrent leurs salles. Notre quête de nos propres origines a libéré des créatures dont les origines étaient fâcheusement proches des nôtres." },
        { "Les Mâcheroc occupent les carrières et les grottes de Dun Morogh, les Brisepierre les vallées du Loch Modan, et les Cavepierre Uldaman même. Des troggs ont aussi envahi Gnomeregan. D'autres sont apparus en Sombrivage et sous Orgrimmar, sans que l'on sache encore comment ils ont traversé la mer." },
        { "Les montagnards demandent de l'aide pour défendre les routes et les établissements, et les gnomes les combattent toujours dans leur capitale. Un voyageur qui porte ce registre trouvera les érudits de Forgefer curieux de l'histoire des troggs ; ceux qui gardent une mine ont un souci plus immédiat : les tenir dehors." },
      },
    },
    ["rogues"] = {
      title = "Voleurs",
      text = {
        { "Chaque cité a ses métiers discrets, et les voleurs les pratiquent tous : la serrure qui s'ouvre sans clé, la bourse qui change de mains à l'insu de son propriétaire, la lame dans le dos. Certains servent une couronne, comme le SI:7 de Hurlevent ; d'autres ne servent que l'or, comme les Défias dans la Marche de l'Ouest et le Syndicat en Alterac." },
        { "Entre les deux se tiennent les assassins de Ravenholdt, dans les collines d'Alterac au-dessus de Hautebrande, qui choisiraient leurs contrats et leurs élèves avec un soin égal. Des voleurs de tous les peuples franchissent ses portes, et rares sont ceux qui parlent de ce qu'ils y ont appris." },
        { "Un voleur combat avec des poisons, des mains vives et la surprise, et s'en va quand le vent tourne. La Ligue en a engagé quelques-uns pour récupérer ce que d'autres lui avaient déjà pris, $gvoyageur:voyageuse;. Ce n'est pas la ligne la plus glorieuse de ses comptes, mais c'est l'une des plus longues." },
      },
    },
    ["royal-apothecary-society"] = {
      title = "La Société royale des apothicaires",
      text = {
        { "La Société royale des apothicaires du maître Faranell sert les Réprouvés par l'alchimie, les poisons et la promesse d'une nouvelle peste. Sylvanas a chargé ses membres de trouver une maladie capable de détruire le Fléau du roi-liche. Leurs préparatifs s'étendent bien au-delà des laboratoires de Fossoyeuse." },
        { "À Brill et à Hautebrande, des voyageurs recueillent du sang et d'autres ingrédients pour des expériences sur des bêtes, des murlocs et des prisonniers. L'apothicaire Lydon contemple la campagne fleurie de Hautebrande et rêve de voir son travail y apporter la mort. Quel que soit l'ennemi déclaré de la Société, ses ambitions à lui englobent clairement les vivants." },
        { "Les Réprouvés savent mieux que quiconque ce que c'est qu'une peste qui vous prend votre foyer. Ce savoir n'a pas rendu tous leurs apothicaires réticents à infliger la même misère au foyer des autres." },
      },
    },
    ["ruins-of-lordaeron"] = {
      title = "Les ruines de Lordaeron",
      text = {
        { "Au-dessus de Fossoyeuse, les rues de la capitale de Lordaeron sont moins vides qu'elles n'en ont l'air depuis la porte. Le Fléau arpente encore en nombre les ruines les plus profondes, et un brouillard impie s'est répandu sur les rues et le vieux cimetière, levé, croient les Gardes noirs, par un nécromancien du nom de Rath'mael, sur le surplomb de Lordamere. Les Réprouvés envoient les forces qu'ils peuvent épargner, et leurs pertes sont telles qu'un paladin du Quartier royal demande aux voyageurs de lui rapporter les membres intacts que laissent les morts." },
        { "Tous ceux qui montent ne le font pas pour la reine banshee. Edward Heartweaver se rendait chaque semaine au cimetière, en quête du fils qu'il avait perdu quand Arthas rasa la cité, jusqu'à la semaine où il ne rentra pas. Et parmi les abominations cousues là-haut, il en est une que les apothicaires appellent le Baron, et qu'ils connaissent sous un nom plus ancien : Othmar Garithos, le seigneur qui fit cause commune avec Sylvanas contre le Fléau et ne survécut pas à l'arrangement. Le capitaine Truman, qui le servait, attend toujours dans les ruines le retour de son commandant." },
        { side = "Horde", aside = true, sign = "P. F.", "De tout ce qui figure sur cette page, c'est la marche hebdomadaire d'Edward Heartweaver qui me revient sans cesse." },
      },
    },
    ["satyrs"] = {
      title = "Les satyres",
      text = {
        { "Xavius aida à ouvrir la cour de la reine Azshara à la Légion ardente. Quand il échoua auprès de Sargeras, le seigneur démon le refaçonna avec des cornes, des sabots et des griffes. Le premier satyre offrit ensuite cette transformation à d'autres elfes avides de pouvoir, et la malédiction se répandit parmi ses fidèles." },
        { "Leurs camps demeurent dans les anciennes terres des elfes de la nuit, au milieu des forêts d'Ashenvale, de Gangrebois et d'Azshara. Autour d'eux, l'eau se souille, les arbres dépérissent et les bêtes se tordent. Les elfes qui tentent de guérir ces bois luttent contre une corruption qui a d'abord pris racine chez leur propre peuple." },
        { "Dix mille ans, c'est long pour soigner une forêt, $gvoyageur:voyageuse;. C'est une durée bien amère pour y trouver ses vieux traîtres encore à l'œuvre." },
      },
    },
    ["scarlet-crusade"] = {
      title = "La Croisade écarlate",
      text = {
        { "Quand le prince Arthas assassina son père et que Lordaeron tomba sous la peste, les paladins de la Main d'argent qui survécurent rassemblèrent ce qu'ils purent et jurèrent de purger la terre des morts par le feu. Trois fondèrent la Croisade : le grand général Abbendis, le grand inquisiteur Isillien et le généralissime Mograine, le Porte-cendres, et à ses débuts, disent ceux qui y étaient, ce fut un ordre noble. Ils devinrent la Croisade écarlate, et ils brûlent depuis : les morts, et les vivants qui les regardent de travers." },
        { "Ils ne font confiance à personne. N'importe quel étranger pourrait porter la peste, n'importe quel elfe ou nain pourrait être un espion, et les Réprouvés sont tout simplement l'ennemi. Depuis le Monastère, dans les clairières de Tirisfal, depuis Âtreval et la Main de Tyr, ils mènent une guerre que personne d'autre n'est invité à gagner. Leur grand croisé, Saidan Dathrohan, les gouverne depuis Stratholme, et leur grand inquisiteur, Isillien, depuis Âtreval." },
        { "La Croisade combat le Fléau, mais la corruption dans ses propres rangs donne une autre raison de s'en méfier. Interrogez le Monastère sur le généralissime Mograine et sa lame, le Porte-cendres, et écoutez bien qui se tait. Et demandez à l'Aube d'argent ce qu'elle a trouvé en regardant de près le grand croisé lui-même." },
      },
    },
    ["scarlet-monastery"] = {
      title = "Le Monastère écarlate",
      text = {
        { "La Croisade écarlate tient un monastère sur une colline du nord de Tirisfal, au-dessus de la mer. Ses murs renferment une bibliothèque, une armurerie, un cimetière et une cathédrale. Chevaliers, prêtres et inquisiteurs s'y forment pour une guerre qui va bien au-delà du Fléau." },
        { "Les Réprouvés sont aussi des ennemis, tout comme n'importe quel voyageur que la Croisade juge suspect. La grande inquisitrice Whitemane et le commandant écarlate Mograine tiennent la cathédrale, tandis que des champions réprouvés sont envoyés contre la forteresse. Le monastère a les dehors d'une maison de la Lumière ; approchez-le avec plus de prudence que cette description ne pourrait le laisser croire." },
        { side = "Horde", aside = true, sign = "P. F.", "Derrière ces murs se trouve une bibliothèque, et dans celle-ci un livre qui leur sert à apprendre à leurs paladins comment détruire les miens. J'envoie des héros le chercher, et je leur demande de le lire avant de le rapporter." },
      },
    },
    ["scourge"] = {
      title = "Le Fléau",
      text = {
        { "Le Fléau est l'armée du roi-liche, une puissance qui siège sur un trône de glace au Norfendre et parle dans l'esprit des morts. Il vint en Lordaeron sous la forme d'une peste, portée dans le grain par un culte d'adorateurs du roi-liche, et tous ceux qui en mangèrent et moururent se relevèrent pour le servir. Le propre prince du royaume, Arthas, acheva l'ouvrage, puis retourna au Norfendre, où il s'empara du Trône de glace." },
        { "Ce qu'il a laissé derrière lui, ce sont les Maleterres : un royaume des morts, avec des goules dans les champs, des abominations cousues de cadavres, et des chaudrons de peste qui empoisonnent la terre. Stratholme est à eux, sous le baron Rivendare, et la Scholomance, et les fermes de la moitié du nord. Désormais, une citadelle noire flotte dans le ciel au-dessus des Maleterres de l'est, Naxxramas, et son maître est la liche Kel'Thuzad." },
        { "Les morts ne se lassent pas, et ils ne s'arrêtent pas. L'Aube d'argent, la Croisade écarlate et les Réprouvés les combattent tous, malgré la méfiance qui les sépare. À la chapelle de l'Espoir de Lumière, l'Aube et la Croisade ont accepté de coopérer contre Naxxramas." },
      },
    },
    ["senjin-village"] = {
      title = "Le village de Sen'jin",
      text = {
        { "Le village de Sen'jin est le foyer des trolls Darkspear sur la côte de Durotar, un ensemble de huttes et de tours de guet qui regarde par-delà le détroit vers les îles de l'Écho. Il porte le nom de Sen'jin, le vieux féticheur et chef des Darkspear, qui accueillit Thrall quand la flotte des orcs fit escale dans ses îles, et qui fut tué par les serviteurs d'une sorcière des mers dans les combats qui suivirent." },
        { "Son fils Vol'jin dirige aujourd'hui la tribu. Les trolls avaient voulu vivre sur les îles de l'Écho, mais l'un de leurs propres féticheurs y a perdu la raison, et depuis, les Darkspear s'entassent sur cette bande de rivage, à regarder par-delà les eaux le foyer qu'ils ont perdu." },
      },
    },
    ["sentinels"] = {
      title = "Les Sentinelles",
      text = {
        { "Quand les druides partirent dormir dans le Rêve d'émeraude, il fallut bien que quelqu'un garde les forêts. Tyrande Whisperwind, grande prêtresse d'Elune, rassembla ses sœurs en une armée de guerrières et les nomma les Sentinelles. Elle demanda à Malfurion de ne pas la quitter pour le Rêve. Il partit tout de même, et elle monta la garde." },
        { "Elles la montèrent dix mille ans, patrouillant Ashenvale la nuit pendant que les druides dormaient, avec les fils de Cénarius, les Gardiens du bosquet, et ses timides filles, les dryades, à appeler en cas de besoin. Tyrande ne cessa jamais de craindre le retour de la Légion. À la fin, elle eut raison." },
        { "Les druides sont éveillés maintenant, et les Sentinelles n'ont pas baissé la garde. Vous les trouverez à chaque poste elfe de la nuit, de Teldrassil à Feathermoon, sous les ordres de leur générale, Shandris Feathermoon. Si l'une d'elles vous regarde comme si elle montait la garde depuis très longtemps, $gvoyageur:voyageuse;, c'est peut-être bien le cas." },
      },
    },
    ["shadow-council"] = {
      title = "Le Conseil des ombres",
      text = {
        { "L'ancienne Horde ne fut jamais tout à fait gouvernée par ses chefs de guerre. Derrière eux se tenait le Conseil des ombres, un cercle secret que le démon Kil'jaeden aida Gul'dan à fonder sur Draenor, pour diriger les clans et répandre parmi eux la magie des démonistes. Ce fut le Conseil qui invoqua Mannoroth pour que les chefs boivent son sang, le Conseil qui fit de Blackhand un chef de guerre qui obéissait aux ordres, et le Conseil, avec Medivh, qui ouvrit la Porte des Ténèbres." },
        { "Doomhammer brisa son emprise en tuant Blackhand et en prenant la Horde pour lui-même, et Gul'dan mourut déchiqueté par les démons qu'il avait lâchés à la tombe de Sargeras. Le nom leur a survécu à tous deux. Des démonistes se rassemblent toujours sous sa bannière, orcs et Réprouvés parmi eux, et traitent toujours avec la Légion." },
        { "Leur plus grand repaire est aujourd'hui Jaedenar, en Gangrebois, où le seigneur des ténèbres Fel'dan conclut ses pactes dans le Fort des ombres, en contrebas. Tandis que les druides peinent à purifier la forêt, les démonistes du Conseil continuent de se rassembler sous ses racines." },
      },
    },
    ["shadowglen"] = {
      title = "Sombrevallon",
      text = {
        { "Sombrevallon rassemble les jeunes recrues des elfes de la nuit autour d'Aldrassil, un grand arbre dont les branches abritent leurs maîtres. Druides, prêtresses et Sentinelles veillent sur ce creux de la forêt de Teldrassil. Son conservateur enseigne que l'équilibre de la nature commence par les petites choses." },
        { "Les recrues ont du travail presque aussitôt. Les araignées sont devenues énormes, et les fées et les grells sont devenus méchants. Un voyageur qui commence ici apprend le souci que les gardiens ont de la forêt en aidant à réparer ce qui s'y est déréglé." },
      },
    },
    ["shamans"] = {
      title = "Chamans",
      text = {
        { "Sur Draenor, les chamans des orcs parlaient avec les éléments et avec leurs ancêtres, jusqu'à ce que les démonistes de Gul'dan en tournent beaucoup vers la magie gangrenée et que les esprits se taisent. Chez les Loup-de-Givre d'Alterac, le vieux chaman Drek'Thar garda vivantes les anciennes voies, et les enseigna à un jeune esclave évadé du nom de Thrall." },
        { "Thrall rendit le chamanisme à son peuple, et en Kalimdor ils en trouvèrent d'autres qui ne l'avaient jamais perdu : les taurens, qui honorent la Terre-Mère, et les trolls, dont les féticheurs avaient gardé le leur. Un chaman demande l'aide de la terre, du feu, de l'eau et de l'air, porte un totem de chacun, et les éléments, la plupart du temps, répondent." },
        { client = "forever", "Depuis peu, on voit aussi des nains en appeler à la pierre et à l'orage, et les Sculpte-vents éolides sont descendus chercher leurs esprits du vent perdus auprès des chamans de la Horde." },
        { "La Ligue a appris à demander la permission d'un chaman avant de fouiller, $gvoyageur:voyageuse;. Le sol a ses opinions, et eux les entendent." },
      },
    },
    ["si-7"] = {
      title = "SI:7",
      text = {
        { "Depuis la caserne de la Vieille ville, Mathias Shaw dirige le service de renseignement de Hurlevent. Le SI:7 suit les affaires qui atteignent rarement un avis public : les Défias, les secrets des nobles, et les endroits où les deux se rencontrent." },
        { "La description du visiteur de Bazil Thredd mena Shaw à un assassin se faisant appeler Marzon, au service du seigneur Gregor Lescovar. L'enquête qui s'ensuivit s'acheva sur la mort des deux hommes dans les jardins du château, hors de portée de la justice ordinaire." },
        { "La caserne offre au service un foyer sans éclat. Son travail mène dans des salons où les ennemis de la cité savent s'habiller très respectablement." },
      },
    },
    ["sickness-of-teldrassil"] = {
      title = "Le mal de Teldrassil",
      text = {
        { "Teldrassil n'a pas reçu les bénédictions qu'Alexstrasza et Nozdormu accordèrent jadis à Nordrassil. Les druides de Dolanaar en parlent sans détour, ainsi que des maux du nouvel arbre : d'étranges bêtes surgissent de son sol, et des créatures autrefois amicales sont devenues violentes." },
        { "La gangremousse s'est emparée d'Ursal le Mutileur et s'est répandue dans sa tribu Pin-tordu. Noiremousse le Fétide, un sylvain, est si envahi que son cœur tranché bat encore sous la sombre végétation. Un seigneur satyre occupe Gangreroche. À Ban'ethil, où des druides de la Serre dorment dans le Rêve d'émeraude selon leur pacte avec Ysera, le gardien s'est tu." },
        { "Fandral reconnaît les problèmes et a des remèdes à proposer. D'autres druides poursuivent leurs recherches. Apportez-leur ce que vous trouvez, $gvoyageur:voyageuse;. Un arbre assez grand pour abriter un peuple est aussi bien grand pour que ses gardiens l'examinent." },
      },
    },
    ["silithid"] = {
      title = "Les silithides",
      text = {
        { "Les silithides occupent de vastes ruches sous le sud de Kalimdor. Leurs guêpes peuvent atteindre la taille d'un chien, leurs ravageurs celle d'un ogre, et leurs fouisseurs sont assez puissants pour effondrer des grottes. Des ruches sont apparues dans les Tarides, à Mille pointes, en Feralas, en Tanaris et à Un'Goro ; c'est en Silithus que se trouve la plus grande concentration." },
        { "Les qiraji d'Ahn'Qiraj les commandent. Il y a mille ans, leurs essaims déferlèrent vers le nord pendant la guerre des Sables changeants, jusqu'à ce que les elfes de la nuit et les dragons scellent la cité derrière le Mur du scarabée. Le Cercle cénarien croit qu'une puissance plus ancienne, sous Ahn'Qiraj, dirige à la fois les maîtres et les serviteurs." },
        { "L'agitation autour des ruches laisse aujourd'hui penser qu'elles se préparent à une grande expansion. Le Cercle surveille de près. Pour un voyageur qui étudie ces insectes, le travail consiste aussi à découvrir jusqu'où s'étendent déjà leurs tunnels et les desseins de leurs maîtres." },
      },
    },
    ["skyborne"] = {
      title = "Les éolides",
      text = {
        { "Les éolides se nomment eux-mêmes shen'dorei, le peuple caché, et jusqu'à ce qu'ils descendent du ciel, la Ligue ignorait leur existence. Leurs ancêtres vivaient à Eldre'Thalas, la cité que les ogres appellent aujourd'hui Hache-tripes, et se soulevèrent contre un prince qui voulait asservir un démon pour nourrir leur magie. Menés par Shal'nan le masqué, ils s'enfuirent par la mer, et des esprits du vent soulevèrent leur île hors du monde, jusqu'au Mur-Céleste." },
        { "L'île de Zéphras y resta suspendue pendant des âges. Aujourd'hui, les esprits du vent ont disparu, l'île se meurt, et les éolides sont descendus chercher de l'aide. L'Ordre suprême cherche le savoir arcanique que leur peuple a perdu et se tourne vers les mages de Dalaran ; les Sculpte-vents cherchent leurs esprits disparus et se tournent vers les chamans de la Horde." },
        { "Ils sont peu nombreux, $gvoyageur:voyageuse;, et ils le savent. Un éolide qui semble ménager chaque vie, la sienne comprise, fait le compte de tous ceux de son peuple qu'il reste encore à perdre." },
      },
    },
    ["sons-of-lothar"] = {
      title = "Les Fils de Lothar",
      text = {
        { "Cinq statues se dressent à la porte de Hurlevent, et chaque plaque se termine de la même façon : présumé mort. Ce sont les commandants de l'Expédition de l'Alliance, qui franchirent la Porte des Ténèbres pour gagner le monde même des orcs après la Deuxième Guerre, quand Ner'zhul et les derniers clans la retraversèrent." },
        { "Khadgar, jadis apprenti de Medivh, les mena, avec le général Turalyon à ses côtés. La forestière elfe Alleria Windrunner partait en éclaireuse pour eux, Kurdran Wildhammer menait les chevaucheurs de griffons, et Danath Trollbane, de Stromgarde, les conseillait. Ils ne purent empêcher Ner'zhul d'ouvrir ses portails vers d'autres mondes, et tandis que Draenor se déchirait, ils choisirent de détruire la Porte des Ténèbres depuis l'autre côté, afin qu'Azeroth ne soit pas entraînée avec lui. Ils réussirent. Quant à savoir si l'un d'eux s'en est échappé, dit le livre de notre bibliothèque, cela reste à voir." },
        { "Lisez les plaques elles-mêmes. Chacune fut écrite par quelqu'un qui connaissait le héros : Falstad pour Kurdran, Uther pour Turalyon, Thoras Trollbane pour son neveu, Antonidas pour Khadgar, à qui il souhaite bonne chance où qu'il soit. Celle d'Alleria fut écrite par sa sœur, Sylvanas, générale des forestiers de Quel'thalas, avant qu'elle ne devienne ce qu'elle est aujourd'hui." },
      },
    },
    ["southsea-freebooters"] = {
      title = "Les Flibustiers des Mers du sud",
      text = {
        { "Les Flibustiers des Mers du sud sont des pirates des mers chaudes de Kalimdor, et ils s'en prennent avant tout aux gobelins, parce que ce sont les gobelins qui ont le plus de choses qui valent d'être volées. Ils tiennent des camps le long de la Côte des marchands, dans les Tarides, au sud de Ratchet, et dans les criques de Tanaris, et leurs navires guettent tout ce qui quitte un port de Gentepression." },
        { "Leur capitaine sur la Côte des marchands est le baron de Longrivage, et Gazlowe, de Ratchet, a mis sa tête à prix ; les gobelins de Gadgetzan paient tout aussi bien pour les pirates de Tanaris. Il n'y a pas de grande histoire derrière eux, ni roi exilé ni cause perdue. Ce sont des voleurs qui possèdent des bateaux, et la mer est vaste." },
      },
    },
    ["steamwheedle-cartel"] = {
      title = "Le cartel Gentepression",
      text = {
        { "Le cartel Gentepression commerce avec l'Alliance comme avec la Horde. Ses gobelins ont compris que des gens prêts à se battre entre eux ont toujours besoin de provisions, et que les deux monnaies valent la peine d'être prises. Leurs villes offrent un endroit où traiter ces affaires." },
        { "Baie-du-Butin, Gadgetzan, Ratchet et Long-guet couvrent la jungle, le désert, la côte et la neige. Des cogneurs y font régner la paix. Revilgaz veille sur Baie-du-Butin, tandis que Gazlowe a du travail pour les visiteurs à Ratchet ; chaque port a des ennuis que le commerce seul ne réglera pas." },
        { "Un voyageur peut y acheter des provisions, y trouver un emploi et y croiser l'autre faction sans porter aussitôt la main à son arme. Le cartel fait payer une bonne partie de ce qu'il offre, mais une halte neutre a sa valeur dans un monde dont les routes traversent tant de guerres." },
      },
    },
    ["stonefields-and-maclures"] = {
      title = "Les Stonefield et les Maclure",
      text = {
        { "Les Stonefield et les Maclure cultivent leurs terres de part et d'autre de la mine de Fargodeep, au sud de Comté-de-l'Or, et les deux familles sont en froid depuis plus longtemps que quiconque ne prend la peine de l'expliquer. Naturellement, Maybell Maclure est amoureuse de Tommy Joe Stonefield. Il attend ses lettres au bord de la rivière, à l'ouest de la ferme de sa famille ; elle attend l'occasion de s'éclipser." },
        { "La grand-mère des Stonefield est du côté des jeunes gens. Elle envoie un mot à son vieil ami William Pestle, à Comté-de-l'Or, qui sait brasser une liqueur d'invisibilité si quelqu'un lui rapporte du varech cristallin pris aux murlocs du lac de Cristal. Grâce à elle, Maybell peut quitter les vignes de sa famille sans être vue. Elle se sent coupable de les tromper, dit-elle, mais pas assez pour rester." },
        { "La querelle continue autour d'eux : une tante Stonefield accuse le jeune Billy Maclure d'avoir volé son collier, Maman Stonefield jure la mort de la truie primée des Brackwell pour avoir mangé ses légumes. Elwynn a vu les Défias, les kobolds et les gnolls aller et venir. Jusqu'ici, la querelle leur a survécu à tous." },
      },
    },
    ["stormwind-city"] = {
      title = "Hurlevent",
      text = {
        { "Hurlevent est la plus grande cité des hommes, et c'est la deuxième Hurlevent à se dresser à cet endroit. La première fut saccagée par la Horde pendant la Première Guerre et brûlée jusqu'aux fondations ; le roi Llane fut assassiné, et son peuple s'enfuit au nord, en Lordaeron, avec le champion Anduin Lothar. Une fois la Deuxième Guerre gagnée, ils revinrent chez eux et la rebâtirent." },
        { "Les maçons de la guilde des Tailleurs de pierre l'élevèrent en pierre blanche, plus belle qu'avant : la cathédrale de la Lumière, les canaux et le donjon qui les domine tous. La Chambre des nobles refusa ensuite de les payer, et le grief des maçons est depuis devenu la Confrérie défias, si bien que la plus belle cité de l'Alliance est aussi celle dont on se souvient avec le plus d'amertume." },
        { client = "classic", "C'est une cité de commerce et de soldats, de prêtres et d'espions, et d'une cour qui chuchote. L'enfant sur le trône en est le roi ; les hommes et les femmes qui l'entourent la gouvernent." },
        { client = "forever", "C'est une cité de commerce et de soldats, avec des navires dans son port, de prêtres et d'espions, et d'une cour qui chuchote. L'enfant sur le trône en est le roi ; les hommes et les femmes qui l'entourent la gouvernent." },
      },
    },
    ["sylvanas-windrunner"] = {
      title = "Dame Sylvanas Windrunner",
      text = {
        { "Sylvanas Windrunner était la générale des forestiers de Lune-d'argent, la plus grande archère des hauts-elfes et la commandante de leurs forestiers, et elle combattit le prince Arthas à chaque pas quand il mena le Fléau en Quel'thalas. Quand il finit par percer, il la tua, et pour la punir de sa résistance, il ne la laissa pas reposer : il la releva sous la forme d'une banshee et la lia à son service." },
        { "Quand le pouvoir du roi-liche vacilla, Sylvanas se libéra. Elle rassembla les morts-vivants qui s'étaient éveillés avec elle, mit un seigneur de l'effroi à son service, et prit pour elle les ruines de la capitale de Lordaeron. Les Réprouvés l'appellent la Dame noire, et ils la suivraient n'importe où." },
        { "Elle était issue d'une famille de forestiers. Sa sœur aînée, Alleria, franchit la Porte des Ténèbres avec l'Expédition de l'Alliance et ne revint jamais ; ce fut Sylvanas qui écrivit les mots de sa plaque, à la porte de Hurlevent. La cadette, Vereesa, était elle aussi forestière de Quel'thalas." },
        { "Elle veut la mort d'Arthas. Au-delà, elle garde ses intentions pour elle, et ses yeux ne trahissent rien." },
        { side = "Horde", aside = true, sign = "P. F.", "Elle nous a rendu notre esprit, ce que la Lumière n'a pas su faire. Ce qu'elle compte faire de nous ensuite, elle ne l'a pas dit." },
      },
    },
    ["syndicate"] = {
      title = "Le Syndicat",
      text = {
        { "Alterac fut le royaume qui vendit l'Alliance à la Horde pendant la Deuxième Guerre, et une fois la guerre gagnée, ses terres furent confisquées et ses nobles déchus de leurs titres. Certains de ces nobles ne l'ont jamais accepté. Ils se font appeler le Syndicat, et ce sont des voleurs et des coupe-jarrets sous la bannière d'un seigneur." },
        { "Leur chef était le seigneur Aliden Perenolde, fils du roi traître, et son rêve était de remettre les orcs aux fers, comme au temps des camps d'internement. Ses gens tiennent la ville en ruine de Strahnbrande, en Alterac, et le donjon de Fort-de-Durn, à Hautebrande, d'où ils détroussent les voyageurs sur les routes d'Austrivage et complotent contre son magistrat, et dans les Hautes-terres Arathies, le seigneur Falconcrest s'est emparé des ruines de Stromgarde elles-mêmes." },
        { "Ils sont nombreux, et ils ne sont pas très doués. Les assassins de Ravenholdt, qui les combattent depuis des années, les traitent de tâcherons, et les Réprouvés ont mis chaque tête à prix. Mais un grand nombre de voleurs peut encore faire beaucoup de mal, et le Syndicat en fait." },
      },
    },
    ["tauren"] = {
      title = "Les taurens",
      text = {
        { "Les taurens comptent parmi les plus anciens peuples des plaines de Kalimdor. Pendant des générations, leurs tribus errèrent, suivant les troupeaux et les voies de la Terre-Mère, tandis que les centaures les harcelaient d'un camp à l'autre. Cairne Bloodhoof rassembla nombre de ces tribus, et quand les orcs de Thrall touchèrent terre, ils aidèrent les taurens à repousser les centaures et à atteindre les prairies de Mulgore." },
        { "Là, les taurens élevèrent Thunder Bluff sur ses mesas et s'établirent, tout en gardant les habitudes de la route. Ils honorent la Terre-Mère, dont les yeux sont An'she, le soleil, et Mu'sha, la lune. Leurs chamans parlent avec les esprits et leurs druides parcourent le Rêve avec le Cercle cénarien. Toutes les tribus ne suivent pas Cairne ; le Totem sinistre garde ses propres conseils et ses propres rancunes." },
        { "Ils sont lents à la colère et très difficiles à arrêter une fois en colère, $gvoyageur:voyageuse;. Les archéologues de la Ligue ont trouvé en eux les hôtes les plus patients de Kalimdor, pourvu que personne ne creuse là où leurs ancêtres sont enterrés." },
      },
    },
    ["teldrassil"] = {
      title = "Teldrassil",
      text = {
        { "Teldrassil est un arbre, et j'écris cette phrase en sachant combien elle paraît sotte. Il s'élève de la mer au large de la côte nord de Sombrivage, si vaste que des forêts poussent sur ses branches et que des rivières courent le long de celles-ci, et les elfes de la nuit vivent dans sa cime. Son nom signifie « couronne de la terre »." },
        { "Les elfes de la nuit avaient autrefois un autre arbre semblable, Nordrassil, sur le mont Hyjal, et tant qu'il se dressait, ils ne vieillissaient jamais. À la fin de la dernière guerre, ils le laissèrent se briser pour détruire le démon Archimonde, et renoncèrent avec lui à leur immortalité. La guerre terminée, les druides menés par Fandral Staghelm firent pousser Teldrassil pour le remplacer." },
        { "L'ancien arbre avait la bénédiction des grands dragons. Le nouveau ne l'a pas, et ses propres gardiens admettent que sa croissance n'a pas été sans défaut. J'en dirai davantage ailleurs. Pour l'heure, prenez le bateau à Auberdine, passez le portail de Rut'theran, et contemplez-le : il n'y a rien de semblable au monde." },
      },
    },
    ["the-agamands"] = {
      title = "Les Agamand",
      text = {
        { "Les Agamand étaient la famille la plus riche de Tirisfal, et ces moulins leur appartenaient. Quand le Fléau arriva, ils fortifièrent la maison et ordonnèrent à tous leurs gens de rester les aider à la tenir. Les ouvriers agricoles restèrent. Ils étaient loyaux, dit l'un d'eux aujourd'hui, et idiots." },
        { "Rien ne tint. La famille et ses ouvriers moururent ensemble et se relevèrent ensemble, et les Agamand hantent toujours les moulins pour le roi-liche : Gregor, le père, Nissa, sa femme, et leurs fils. Leur crypte se trouve au nord du domaine, au milieu du Fléau." },
        { "Certains de leurs ouvriers se sont libérés et sont aujourd'hui des Réprouvés. Coleman Farthing, qui travaillait à leurs moulins, renvoie des voyageurs détruire ce qui reste de la famille et dépouiller leur crypte de ses biens de famille. La vengeance, dit-il, a un goût sucré ; il espère qu'ils ont connu la peur avant la fin. C'est un espoir stupide, admet-il. Il le garde quand même." },
      },
    },
    ["the-ashbringer"] = {
      title = "Le Porte-cendres",
      text = {
        { "Le Porte-cendres fut un homme avant d'être une épée. Le généralissime Mograine fonda la Croisade écarlate avec le grand général Abbendis et le grand inquisiteur Isillien, quand c'était encore un ordre noble, et on l'appelait le Porte-cendres pour ce qu'il faisait aux armées du roi-liche : il entrait dans des bataillons entiers de morts-vivants et en ressortait de l'autre côté sans rien laisser derrière lui que des cendres. Sa lame prit son nom." },
        { "Le grand inquisiteur Fairbanks, qui était présent, raconte comment cela finit. Le grand croisé passa un marché avec Kel'Thuzad, et Mograine fut attiré dans une embuscade à Stratholme par son propre fils, Renault. Tandis que le Fléau se refermait sur eux et que la lame se mettait à luire, Renault la ramassa et la planta dans le dos de son père. « Qu'as-tu fait, Renault ? » furent les derniers mots du généralissime. L'homme et la lame ne faisaient qu'un, et le meurtre les corrompit tous deux ; Mograine se releva en chevalier de la mort au service de Kel'Thuzad." },
        { "Fairbanks s'échappa de Stratholme après deux jours parmi les morts et raconta l'histoire à quiconque voulait l'entendre au Monastère. On l'assassina pour cela et on le cacha dans sa cathédrale. Mais certains l'avaient entendu, dit-il, et c'est ainsi que naquit l'Aube d'argent. Renault dirige aujourd'hui le Monastère, en tant que commandant écarlate." },
      },
    },
    ["the-bulwark"] = {
      title = "La Barricade",
      text = {
        { "La Barricade est le mur que les Réprouvés ont élevé à la lisière est de Tirisfal, là où finissent les clairières et où commencent les Maleterres, et ils le tiennent jour et nuit contre le Fléau. Des Gardes noirs en tiennent la porte, et des officiers de l'Aube d'argent y ont aussi un poste, ce qui en dit long sur la crainte que leur inspire à tous ce qui se trouve au-delà." },
        { "On trouve des choses plus étranges à la Barricade. Alexi Barov, le dernier d'une maison noble de Lordaeron qui vendit son château au Culte des damnés, y tient compagnie aux Réprouvés, et a sur la fortune de sa famille des opinions qu'il partage volontiers." },
      },
    },
    ["the-crusades-fallen"] = {
      title = "Les morts de la Croisade",
      text = {
        { "Le Monastère écarlate enterre ses héros dans son propre cimetière, et leurs pierres en disent plus sur la Croisade que ses sermons. Lisez-les et vous découvrirez qu'elle ne fut jamais un simple ordre humain de Lordaeron : un grand sorcier et un capitaine des forestiers citoyens de Quel'thalas, des assassins de Dalaran, un guerrier d'Alterac, un seigneur des Cavernes rouges, un amiral de Kul Tiras." },
        { "Lisez plus loin et vous verrez jusqu'où elle est allée. Orman de Stromgarde, son premier capitaine général, se perdit à l'entrée du glacier de la Couronne de glace ; le grand amiral de la Flotte écarlate, au large de la côte gelée du Norfendre ; le premier maître assassin, sur les rivages du Norfendre. La Croisade a porté sa guerre jusqu'à la porte même du roi-liche, et les pierres sont ce qui en est revenu." },
        { "D'autres tombèrent plus près de chez eux : un grand abbé tué en défendant le Monastère lui-même, un défenseur mort en terrassant un seigneur de l'effroi, un elfe pris dans un combat sans fin contre un nécromancien. Quoi que la Croisade soit devenue depuis, $gvoyageur:voyageuse;, ce furent les premiers à croire en elle." },
        { side = "Horde", aside = true, sign = "P. F.", "J'ai lu ces pierres, moi aussi. J'en suis revenu avec un récit moins généreux." },
      },
    },
    ["the-forsaken"] = {
      title = "Les Réprouvés",
      text = {
        { "Quand l'emprise du roi-liche sur ses morts faiblit, certains d'entre eux s'éveillèrent. Ils étaient toujours morts, mais leur esprit leur appartenait de nouveau, et ils se souvenaient de ce qu'ils avaient été et de ce qu'on leur avait fait. Ils se nomment les Réprouvés, et ils suivent celle qui les a libérés : Sylvanas Windrunner, la reine banshee." },
        { "Ils ont repris la ruine de la capitale de leur royaume et bâti une cité en dessous, et ils mènent leur propre guerre contre le Fléau qui les a faits. Ils ont rejoint la Horde, qui avait besoin d'alliés contre l'Alliance, et la Horde les a acceptés, ce dont les Réprouvés avaient plus besoin encore. Ce n'est pas une amitié chaleureuse." },
        { "Je ne prétendrai pas que les Réprouvés soient une compagnie facile. La plupart étaient des hommes et des femmes de Lordaeron, qui se souviennent de leur ancienne vie et ne peuvent y retourner. Ce qu'ils veulent aujourd'hui, au-delà de se venger du roi-liche, personne hors de Fossoyeuse ne saurait le dire." },
        { side = "Horde", aside = true, sign = "P. F.", "Personne hors de Fossoyeuse ne saurait dire ce que nous voulons, écrit-elle. La plupart d'entre nous, à l'intérieur, ne le sauraient pas non plus. Moi, je veux savoir ce qu'on nous a fait, et l'écrire comme il faut." },
      },
    },
    ["the-stockade"] = {
      title = "La Prison",
      text = {
        { "La prison de Hurlevent se trouve sous ses canaux, taillée dans la roche sous la cité. Parmi les Défias qui y étaient enfermés se trouvait le lieutenant d'Edwin VanCleef, Bazil Thredd. Sous sa conduite, les détenus se soulevèrent et prirent le contrôle des cellules." },
        { "Le gardien fit appel à des aventuriers pour mater la révolte. Thredd n'était pas le seul prisonnier dangereux à l'intérieur : l'orc Targorr le Terrifiant comptait parmi les émeutiers. C'est un sentiment désagréable que d'avoir une place forte ennemie sous les rues de sa propre capitale." },
      },
    },
    ["thrall"] = {
      title = "Thrall",
      text = {
        { "Thrall est le chef de guerre de la Horde, et sa vie se lit comme une ballade que personne ne croirait. Il était le fils de Durotan, chef des Loup-de-Givre, trouvé nourrisson auprès de ses parents assassinés et élevé comme esclave et gladiateur au donjon de Fort-de-Durn par son maître, le seigneur Aedelas Blackmoore, qui voulait en faire le général d'une armée d'orcs domptés. On lui donna le nom de Thrall, qui signifie esclave, et il le garda." },
        { "Il s'évada, aidé par une jeune humaine qui s'était liée d'amitié avec lui, retrouva le clan de son père dans les montagnes d'Alterac et apprit les voies du chaman. Puis, avec Grom Hellscream et le vieux chef de guerre Orgrim Doomhammer, il força les camps d'internement et libéra son peuple. Doomhammer tomba dans cette guerre et laissa à Thrall la Horde et son marteau." },
        { "Il mena la Horde par-delà la mer jusqu'à Kalimdor, combattit aux côtés des elfes de la nuit et des humains contre la Légion ardente, et bâtit Durotar. Il veut la paix avec l'Alliance, et l'a faite avec Jaina Proudmoore de Theramore. Quant à savoir si le reste de l'Alliance la veut, c'est une autre question." },
        { side = "Horde", aside = true, sign = "P. F.", "Lordaeron a fait de lui un esclave, et il a pourtant trouvé de la place dans sa Horde pour les morts de Lordaeron. Je ne suis pas sûr que j'en aurais fait autant." },
      },
    },
    ["thunder-bluff"] = {
      title = "Thunder Bluff",
      text = {
        { "Thunder Bluff se dresse tout en haut des mesas de Mulgore, et l'on y accède par de grands ascenseurs ou à dos de coursier du vent. Des ponts de corde relient ses cimes. Un nain de Forgefer habitué aux sols bien solides fera peut-être bien de regarder où il met les pieds avant de regarder la vue." },
        { "Cairne a bâti ce refuge après que les taurens et les orcs eurent repoussé les centaures. Des tribus longtemps habituées à l'errance s'y sont rassemblées. Marchands et artisans le partagent désormais avec les chasseurs, les druides de la cime des Anciens, et les chamans et les voyants de la cime des Esprits." },
        { "Cairne demeure grand chef en son centre. Le Totem sinistre compte parmi ceux qui s'opposent à son autorité. Un voyageur y voit un peuple qui a enfin une cité, même si un foyer permanent n'a pas mis fin aux désaccords entre ses tribus." },
      },
    },
    ["timber"] = {
      title = "Grumeux",
      text = {
        { "Les chasseurs de Kharanos l'appellent Grumeux : un loup plus grand que ses congénères, qui comprend les pièges un peu trop bien. On dit qu'il choisit son terrain et revient sur ses propres traces. Il a survécu à tous les chasseurs lancés à ses trousses." },
        { "Les loups figurent rarement dans une histoire royale. Celui-ci a plaidé sa cause avec assez d'arguments pour y entrer, même si je doute qu'il apprécie l'honneur." },
        { "Si vous l'avez tué, $gvoyageur:voyageuse;, notez ce qui s'est passé tant que vous vous en souvenez. Les chasseurs auront bien assez tôt leur propre version." },
      },
    },
    ["timbermaw"] = {
      title = "Les Grumegueules",
      text = {
        { "De toutes les tribus furbolgs du nord, seuls les Grumegueules ont gardé leur raison. La corruption qui a suinté de Gangrebois a changé les Mort-bois et les Tombe-hiver en ces créatures grondantes que l'on croise sur les routes, et les Grumegueules ont dû regarder cela arriver aux leurs. Ils ont tenu bon dans leurs tunnels sous les montagnes, entre Gangrebois, Reflet-de-Lune et le Berceau-de-l'Hiver, et les ont tenus contre tout le monde." },
        { "Ils ont des raisons d'être prudents. La plupart des voyageurs tuent désormais n'importe quel furbolg à vue, sans demander à quelle tribu il appartient, si bien que les Grumegueules se fient à très peu de gens. Aidez-les contre les tribus corrompues et ils commenceront, lentement, à vous laisser traverser leur repaire. On a trouvé un démon à la racine de la folie des Tombe-hiver ; le tuer a donné à cette tribu, selon les mots des Grumegueules, une chance de survivre." },
        { "Ils ne prennent aucun plaisir à combattre leurs propres frères. L'un de leurs éclaireurs demande à ceux qui se battent pour lui de lui épargner les détails. Gagnez pleinement leur confiance et ils enverront une offrande de paix à votre propre roi. C'est la chose la plus courtoise qu'un peuple assiégé ait offerte à quiconque dans ce registre." },
      },
    },
    ["tiragarde-keep"] = {
      title = "Le donjon de Tiragarde",
      text = {
        { "Le donjon de Tiragarde est une forteresse de Kul Tiras sur la côte de Durotar, et il ne devrait pas être là du tout. Quand la Horde se fut établie sur sa nouvelle terre, l'amiral Daelin Proudmoore, seigneur du royaume insulaire de Kul Tiras, fit traverser la mer à sa flotte pour achever la guerre que son peuple n'avait jamais pardonnée, au mépris de la paix que sa propre fille avait conclue avec Thrall au mont Hyjal. Il fut vaincu et tué, et sa flotte gît en épave au large de cette plage." },
        { "Le donjon tomba avec lui. Mais certains de ses hommes restèrent, et sous un certain lieutenant Benedict et un commandant de la garde nommé Zalaphil, ils l'ont repris et fortifié : une poignée de Kultirassiens au milieu du pays natal de la Horde. Les orcs de Tranchecolline les traitent de traîtres. Les Kultirassiens en diraient à peu près autant de Theramore." },
      },
    },
    ["tirisfal-glades"] = {
      title = "Clairières de Tirisfal",
      text = {
        { "Tirisfal était le cœur du royaume de Lordaeron : des terres agricoles vallonnées, des vergers et des moulins autour de la capitale, la contrée la plus riche du nord. C'est aussi une vieille terre à d'autres égards ; les clairières ont donné leur nom à l'ordre secret des mages, les Gardiens de Tirisfal, qui veillèrent sur le monde pendant des siècles." },
        { "C'est aujourd'hui une terre grise. La peste a pris Lordaeron, les morts ont marché, et la capitale est tombée. Les fermes sont vides, ou pire, les arbres sont sans feuilles et la lumière est toujours pâle. Les Réprouvés la gouvernent depuis les profondeurs de la cité en ruine, la Croisade écarlate depuis son monastère du nord, et le Fléau erre toujours dans les champs entre les deux." },
      },
    },
    ["twilights-hammer"] = {
      title = "Le Marteau du crépuscule",
      text = {
        { "Le Marteau du crépuscule de Cho'gall fut d'abord un clan orc de la Deuxième Guerre, mené par un ogre-mage à deux têtes. Il combattait dans la conviction que le monde devait finir. La défaite de l'ancienne Horde a laissé ce dessein vivant dans un culte aux fidèles venus de bien des peuples." },
        { "Le culte vénère les Dieux très anciens, des puissances primordiales sous la terre. Ses membres servent une horreur dans les profondeurs de Brassenoire, se rassemblent autour d'idoles dans la gorge des Vents brûlants et invoquent des seigneurs élémentaires en Silithus." },
      },
    },
    ["tyrande-whisperwind"] = {
      title = "Tyrande Whisperwind",
      text = {
        { "Tyrande Whisperwind guide les elfes de la nuit en tant que grande prêtresse d'Elune. Il y a dix mille ans, c'était une jeune prêtresse qui combattait la Légion aux côtés de Malfurion et d'Illidan Stormrage. Elle aimait Malfurion ; l'amour qu'Illidan lui portait resta sans réponse. Ce fut elle qui persuada les autres que Malfurion avait raison et que le Puits devait être détruit, et avant la fin, les satyres d'Azshara la firent prisonnière. En chemin, elle recueillit une jeune archère orpheline, Shandris Feathermoon, qui commande aujourd'hui les Sentinelles en tant que générale." },
        { "Pendant que les druides dormaient dans le Rêve d'émeraude, ses prêtresses et ses Sentinelles gardèrent les forêts au fil des longs âges. Pendant la Troisième Guerre, elle rallia les elfes de la nuit, réveilla Malfurion et se tint à Hyjal quand Archimonde tomba." },
        { "Malfurion a désormais disparu, et les druides ignorent son sort. Tyrande gouverne depuis le temple de la Lune de Darnassus, tandis que Fandral Staghelm est à la tête des druides. Recevez son accueil avec respect, $gvoyageur:voyageuse;. La prêtresse qui salue les visiteurs a mené son peuple à travers des guerres bien plus anciennes que nos royaumes." },
      },
    },
    ["undercity"] = {
      title = "Fossoyeuse",
      text = {
        { "La capitale de Lordaeron gît en ruine au-dessus de la propre cité des Réprouvés. Derrière ses murailles brisées se trouvent la salle du trône dévastée et des cours sans vie. En dessous, de vieilles cryptes et des catacombes sont devenues Fossoyeuse, disposée autour d'anneaux de bave verte. Sylvanas tient sa cour dans son quartier royal." },
        { "Marchands, maîtres et gardes occupent les autres quartiers, et la Société royale des apothicaires travaille à l'Apothicarium. Les Réprouvés ont fait une capitale qui fonctionne sous l'épave de celle qu'ils ont connue de leur vivant. Un voyageur qui ne regarderait que les ruines d'en haut manquerait l'endroit où se traitent désormais les affaires qui restent au royaume." },
        { side = "Horde", aside = true, sign = "P. F.", "Elle a raison pour l'Apothicarium, jusqu'à un certain point. Vous m'y trouverez, sur le plus au sud de ses deux ponts, où je pose des questions aux héros qui croient que la force suffit. Venez vous faire examiner, $gvoyageur:voyageuse;." },
      },
    },
    ["valley-of-trials"] = {
      title = "La vallée des Épreuves",
      text = {
        { "La vallée des Épreuves est l'endroit où l'on met à l'épreuve les jeunes de la Horde : orcs et trolls, envoyés parmi les sangliers et les scorpides du canyon pour montrer ce qu'ils valent. C'est un endroit étroit, brûlé de soleil, au sud de Tranchecolline, et ses épreuves sont faites pour être dures." },
        { "Tous ses dangers ne sont pas des bêtes. Dans les grottes de la vallée, la Lame ardente a caché ses sectateurs et ses diablotins, assez près des jeunes de la Horde pour que ce soit une insulte, et la première leçon que beaucoup d'orcs apprennent, c'est que le plus vieil ennemi de leur peuple porte parfois un visage d'orc." },
      },
    },
    ["varimathras"] = {
      title = "Varimathras",
      text = {
        { "Quand Arthas partit pour le Norfendre, Varimathras et ses frères seigneurs de l'effroi régnèrent sur les ruines de Lordaeron. Sylvanas, tout juste libérée de l'emprise du roi-liche, le vainquit et lui offrit le choix entre la servitude et la mort. Il choisit la servitude, puis l'aida à se retourner contre ses frères." },
        { "Il se tient désormais aux côtés de la reine banshee, à Fossoyeuse. C'est une association imposante, même si ses débuts n'offrent guère de garanties sur la loyauté de l'un ou de l'autre. Varimathras a trouvé le moyen de survivre à un changement de maître ; Sylvanas l'a gardé là où elle peut le voir." },
        { side = "Horde", aside = true, sign = "P. F.", "Nous le croisons dans le Quartier royal sans rien dire. Je suis moins sûr que la Dame noire semble l'être que le garder près de soi revienne à le garder loyal." },
      },
    },
    ["venture-company"] = {
      title = "La KapitalRisk",
      text = {
        { "Si une chose peut être déterrée, abattue ou pompée hors du sol, la KapitalRisk est déjà là avec un déchiqueteur. C'est une affaire gobeline, une compagnie commerciale qui n'est loyale qu'envers son conseil d'administration, et dont le métier consiste à prendre ce qui appartient aux autres et à le vendre avant qu'ils s'en aperçoivent." },
        { "En Kalimdor, on la trouve partout. Elle rase les forêts des Serres-Rocheuses, elle a creusé des mines dans les falaises de Mulgore malgré le refus exprès des taurens et souillé leurs puits par la même occasion, et dans les Tarides elle a pompé la Videfange jusqu'à en faire une mare noire de pétrole. De l'autre côté de la mer, elle exploite le bois de la jungle de Strangleronce et creuse ses collines." },
        { "Les siens en pensent peu de bien. Les gobelins du cartel Gentepression, qui tiennent les ports neutres, paieront bien quiconque rend la vie difficile à la Compagnie, et j'imagine que chaque tauren de Mulgore en fera autant." },
      },
    },
    ["voljin"] = {
      title = "Vol'jin",
      text = {
        { "Vol'jin dirige les Darkspear et c'est un chasseur des ombres, l'un de leurs prêtres-guerriers qui marchent avec les loas. Son père Sen'jin mourut pendant les combats sur les îles où la flotte de Thrall rencontra la tribu pour la première fois. Vol'jin a maintenu l'engagement de son père envers la Horde." },
        { "Il reste près de Thrall à Orgrimmar tandis que son peuple tient le village de Sen'jin et se tourne vers la reconquête des îles de l'Écho. Un voyageur qui cherche le chef des Darkspear le trouvera donc dans la capitale, avec le foyer perdu de la tribu toujours parmi ses soucis." },
      },
    },
    ["war-of-the-three-hammers"] = {
      title = "La guerre des Trois Marteaux",
      text = {
        { "Il y a quelque deux siècles et demi, Forgefer appartenait à trois clans à la fois. Les Bronzebeard, les Wildhammer et les Sombrefer vivaient sous un même haut roi, Modimus Courbenclume, et à sa mort ils ne purent s'entendre sur son successeur." },
        { "La querelle devint une guerre sous la montagne. Les Bronzebeard tinrent la cité. Les Wildhammer, menés par le thane Khardros, en furent chassés et élevèrent leur propre forteresse à Grim Batol, et les Sombrefer du thane-sorcier Thaurissan se retirèrent dans les montagnes du sud." },
        { "Les Sombrefer n'en avaient pas fini. Ils marchèrent à la fois sur Forgefer et sur Grim Batol, et perdirent les deux batailles. Dans sa fureur, Thaurissan fit appel à une puissance bien plus ancienne que n'importe quel clan et réveilla Ragnaros, le seigneur du Feu. Le sud brûla : la gorge des Vents brûlants et les Steppes ardentes sont ce qu'il en resta, et depuis, les Sombrefer servent le seigneur du Feu dans le mont Rochenoire." },
        { "Les Wildhammer ne restèrent pas non plus à Grim Batol. La mort de la reine Modgud, tuée à ses portes, laissa une noirceur dans la pierre, et ils se firent un nouveau foyer au Nid-de-l'Aigle, dans les Hinterlands. Forgefer se souvient encore de quel clan est resté." },
      },
    },
    ["warlocks"] = {
      title = "Démonistes",
      text = {
        { "Gul'dan apporta la magie démoniste dans la Horde orc. Lui et son Conseil des ombres l'avaient apprise de Kil'jaeden, et grâce à elle ils firent de leur peuple une arme de la Légion ardente. Les démonistes de la Horde relevèrent les morts, invoquèrent des démons et brûlèrent des contrées entières, et leur art survécut à leurs maîtres." },
        { "On trouve aujourd'hui ses élèves des deux côtés. La Lame ardente sert toujours la Légion en Durotar ; les démonistes de Hurlevent se tiennent dans la cave de l'Agneau assassiné ; les gnomes et les Réprouvés l'étudient aussi. Un démoniste lie des démons à son service, jette des malédictions, et paie le pouvoir de sa propre vie quand rien d'autre ne suffit." },
        { client = "forever", "Les Darkspear comptent désormais eux aussi des démonistes parmi leurs lanceurs de sorts." },
        { "La plupart des cités tolèrent les démonistes sans leur faire confiance, $gvoyageur:voyageuse;, et les démonistes semblent préférer qu'il en soit ainsi." },
      },
    },
    ["warriors"] = {
      title = "Guerriers",
      text = {
        { "Il n'existe pas d'ordre unique des guerriers, $gvoyageur:voyageuse;, seulement un métier aussi vieux que la première querelle. Les fantassins de Lordaeron et les chevaliers de Hurlevent, les grunts orcs qui ont abattu ces mêmes murailles, les braves taurens des plaines et les chasseurs Darkspear des îles ont appris les mêmes leçons par des chemins différents." },
        { "Le métier a pourtant ses écoles. Un guerrier apprend à se tenir de trois façons : au combat, pour frapper le premier et fort ; en défense, derrière un bouclier, pour tenir une ligne ; et dans la fureur du berserker, qui dépense sans compter les forces du corps et les lui réclame plus tard. L'essentiel du travail consiste à savoir laquelle le moment exige." },
        { "Chaque capitale a une salle où les guerriers forment les jeunes. La Ligue en engage un bon nombre comme escortes, et je n'en ai encore jamais rencontré un qui n'ait pas d'avis sur l'endroit où les fouilleurs devraient creuser." },
      },
    },
    ["wendigos"] = {
      title = "Les wendigos",
      text = {
        { "L'antre Gris offre un abri contre la neige de Dun Morogh, pourvu que vous parveniez à convaincre ses wendigos de le partager. Un coursier qui les a fuis y a laissé derrière lui une cargaison de munitions. Les créatures ont eu le dernier mot." },
        { "Le pilote Stonegear veut leurs crinières pour en faire un tapis dans son engin de siège. Même une machine a besoin d'un peu de confort dans ce pays, $gvoyageur:voyageuse;. Pour récupérer les munitions comme pour meubler l'engin, il faut approcher un wendigo de bien plus près que le coursier n'a voulu le faire." },
      },
    },
    ["whitemane-and-mograine"] = {
      title = "Whitemane et Mograine",
      text = {
        { "La grande inquisitrice Sally Whitemane et le commandant écarlate Renault Mograine tiennent la cathédrale du Monastère écarlate. Il commande ses chevaliers ; elle guide sa foi. Sa maîtrise de la Lumière peut le relever quand il tombe, ce qui rend une victoire sur le commandant moins définitive qu'un voyageur pourrait l'espérer." },
        { "Renault est le fils du généralissime Alexandros Mograine, le Porte-cendres, un grand champion de la Main d'argent contre le Fléau. Son père est mort. Fairbanks, un autre grand inquisiteur caché dans la cathédrale, prétend savoir comment il est mort et affirme que Renault était là. La Croisade préférerait son silence. Ceux qui apportent la lame du généralissime entendront peut-être le récit qu'elle ne veut pas voir raconté ; la page du Porte-cendres, dans ce registre, rapporte ce qu'il dit." },
        { side = "Horde", aside = true, sign = "P. F.", "Whitemane relève son commandant d'entre les morts, et la Croisade brûle le reste d'entre nous pour moins que ça." },
      },
    },
    ["wildkin"] = {
      title = "Les chouettards",
      text = {
        { "On appelle les grands hiboux-ours du nord chouettards, ou séléniens, et les elfes de la nuit les traitent avec une révérence que les voyageurs ne partagent pas toujours. On raconte qu'Elune elle-même les aurait créés, et certains disent qu'ils étaient ses compagnons. Une érudite elfe de la nuit qui étudie leurs plumes y trouve une magie que ces créatures ne manient pas tant qu'elles ne la portent, comme une part de leur nature même." },
        { "Ils sont capables d'une grande douceur comme d'une grande férocité, surtout quand quelque chose qu'ils tiennent pour important est menacé, et au Berceau-de-l'Hiver on dit qu'ils gardent des secrets des elfes de la nuit. Certains y sont devenus fous, disent les rapports, pour être restés trop longtemps près de la chose même qu'ils protègent." },
        { "Ces derniers temps, les doux se font plus rares. Les séléniens de Sombrivage sont attirés par un grand cristal rouge dans les collines de l'est, et les Sentinelles d'Auberdine ne les croient plus inoffensifs. Je laisserais une large place à n'importe quel chouettard, $gvoyageur:voyageuse;, et une plus large encore à un chouettard fou." },
      },
    },
    ["wintersaber-trainers"] = {
      title = "Les Éleveurs de sabres-d'hiver",
      text = {
        { "Tout en haut du roc des Sabres-de-Givre, au nord du Berceau-de-l'Hiver, une poignée d'elfes de la nuit élèvent les sabres blancs du nord. Leur chef, Rivern Frostwind, reste à l'écart ; sa présence passe inaperçue aux yeux de la plupart, dit-il, ce qui lui convient." },
        { "Les félins ne se méritent pas facilement. Rivern commence par envoyer quiconque en veut un chercher de la viande, de chimère et d'ours Crocs acérés, pour nourrir les jeunes sabres en dressage, puis l'appelle à l'aide contre les furbolgs Tombe-hiver qui harcèlent le roc. C'est un long apprentissage, et peu le terminent." },
        { "Ceux qui y parviennent quittent le Berceau-de-l'Hiver sur un sabre-de-givre, ce qui vaut chaque course, m'a-t-on dit. Les félins, pour leur part, semblent penser que l'arrangement était leur idée." },
      },
    },
    ["worgen"] = {
      title = "Les worgens",
      text = {
        { "Arugal fit venir des worgens d'un autre monde alors que les défenseurs de Dalaran tombaient sous le Fléau. Les hommes-loups attaquèrent les morts, puis se retournèrent contre les vivants. Le mage se retira au donjon d'Ombrecroc, les appela ses enfants et maudit Bois-du-Bûcher, dont les habitants sont humains le jour et worgens la nuit." },
        { "Le Bois de la Pénombre offre une autre piste. Les Veilleurs signalent leur apparition soudaine dans une mine au sud de Sombre-Comté. Des récits pointent vers la Faux d'Elune, une ancienne relique elfique apportée dans la forêt par quelqu'un qui ne comprenait pas son pouvoir." },
        { "Ces créatures sont fortes, rusées, et capables de courir à quatre pattes malgré leur posture droite. Gardez les deux pistes distinctes, $gvoyageur:voyageuse;. Savoir qui les a amenées dans une forêt n'a pas expliqué leur apparition dans l'autre." },
      },
    },
  },
})
